    /// PIN (user ruling 2026-08-19) — **a scheme the reader wrote reveals a
    /// pencil and a ×; a bundled one reveals nothing.**
    ///
    /// The absence is the sentence. Ten schemes travel inside the executable and
    /// have no file anywhere to open or move, so there is nothing to grey out —
    /// which is what the line `Deleting sends this scheme's file to the Recycle
    /// Bin` used to have to say under three buttons.
    ///
    /// Red gate: place the run on every item and the bundled assertion goes red;
    /// hit-test the item before the marks and a press on the pencil chooses the
    /// scheme it was meant to open.
    #[test]
    fn only_a_scheme_the_reader_wrote_carries_the_two_marks() {
        let files = scheme_file_lines();
        let rows = flat_rows();
        let lines = shortcut_lines();
        let content = SettingsContent {
            rows: &rows,
            shortcuts: &lines,
            profiles: &[],
            scheme_files: &files,
            advanced: every_group_open(),
            advanced_reveal: None,
            editor: None,
            values: Box::leak(Box::new(SettingsValues::sample())),
        };
        let row = SettingsRow::DarkScheme;
        let open = shaped_picker(&files, Some(row), UNSCROLLED);
        for index in 0..row.option_count() {
            let mine = menu_item_is_user_file(row, index, content);
            let acts = open.menu_acts[index];
            assert_eq!(
                acts.is_some(),
                mine,
                "item {index} ({:?}) is a file: {mine}, and its marks say {:?}",
                row.option_label(index),
                acts.is_some()
            );
            let Some(acts) = acts else {
                continue;
            };
            // Both marks answer where they are drawn, and the item still answers
            // everywhere they are not.
            for (box_of, expected) in [
                (acts.edit, SettingsTarget::MenuItemEdit(row, index)),
                (acts.delete, SettingsTarget::MenuItemDelete(row, index)),
            ] {
                let (x, y) = centre(box_of);
                assert_eq!(
                    hit(&open, &values(), x, y),
                    expected,
                    "a mark on item {index} answers for itself"
                );
                assert!(
                    box_of[2] <= open.items[index][2] && box_of[0] > open.items[index][0],
                    "and it is inside its own item's trailing half"
                );
            }
            let (x, _) = centre(open.items[index]);
            assert_eq!(
                hit(&open, &values(), x, centre(open.items[index]).1),
                SettingsTarget::Choice(row, index),
                "the item's own words still choose the scheme"
            );
            assert!(
                x < f64::from(acts.edit[0]),
                "the words end before the marks begin"
            );
        }
        // The action at the foot is not an item that can carry marks.
        assert_eq!(
            open.menu_acts[row.option_count()],
            None,
            "the verb is not a file"
        );
    }

    /// PIN (user ruling 2026-08-19) — **`←` and `→` reach the two marks, `↑`
    /// and `↓` put the column back.**
    ///
    /// A picker is walked with the vertical keys and always has been, so the row
    /// is the unit they move between and the marks are a second axis on the row
    /// the walk is standing on. The reset is the half that matters: a reader who
    /// moves to another scheme is choosing a scheme, and landing on somebody's
    /// `×` because the row above left the highlight there is the one thing this
    /// surface must never do.
    ///
    /// Red gate: let `step_menu_column` wrap and `←` from the item lands on the
    /// `×` two columns away; fold only `Choice` into `step`'s menu arm and the
    /// ring stops answering `↑` once it has walked into a mark.
    #[test]
    fn the_arrows_walk_a_scheme_row_into_its_marks_and_back() {
        let files = scheme_file_lines();
        let rows = flat_rows();
        let lines = shortcut_lines();
        let content = SettingsContent {
            rows: &rows,
            shortcuts: &lines,
            profiles: &[],
            scheme_files: &files,
            advanced: every_group_open(),
            advanced_reveal: None,
            editor: None,
            values: Box::leak(Box::new(SettingsValues::sample())),
        };
        let row = SettingsRow::DarkScheme;
        let mine = (0..row.option_count())
            .find(|index| menu_item_is_user_file(row, *index, content))
            .expect("the fixture holds a file of the reader's own");
        let bundled = (0..row.option_count())
            .find(|index| !menu_item_is_user_file(row, *index, content))
            .expect("and a bundled scheme");
        let mut panel = SettingsPanel::default();
        panel.toggle(content);
        panel.select_category(SettingsCategory::Appearance);
        panel.press(SettingsTarget::Choice(row, mine));
        panel.press(SettingsTarget::Combo(row));
        panel.key(SettingsKey::Activate, content, &values());
        // Land the ring on the file, whatever the value in force is.
        panel.press(SettingsTarget::Combo(row));
        panel.key(SettingsKey::Activate, content, &values());
        panel.focus_to(SettingsTarget::Choice(row, mine));
        for (key, expected) in [
            (SettingsKey::Right, SettingsTarget::MenuItemEdit(row, mine)),
            (
                SettingsKey::Right,
                SettingsTarget::MenuItemDelete(row, mine),
            ),
            (
                SettingsKey::Right,
                SettingsTarget::MenuItemDelete(row, mine),
            ),
            (SettingsKey::Left, SettingsTarget::MenuItemEdit(row, mine)),
            (SettingsKey::Left, SettingsTarget::Choice(row, mine)),
            (SettingsKey::Left, SettingsTarget::Choice(row, mine)),
        ] {
            panel.key(key, content, &values());
            assert_eq!(
                panel.focus(),
                Some(expected),
                "{key:?} on a file's row walks its own columns and stops at both ends"
            );
        }
        // A bundled row has one column and the arrows do nothing on it.
        panel.focus_to(SettingsTarget::Choice(row, bundled));
        panel.key(SettingsKey::Right, content, &values());
        assert_eq!(
            panel.focus(),
            Some(SettingsTarget::Choice(row, bundled)),
            "a row with no file has no second axis"
        );
        // And a vertical step from inside a mark puts the column back.
        panel.focus_to(SettingsTarget::MenuItemDelete(row, mine));
        panel.key(SettingsKey::Down, content, &values());
        assert!(
            matches!(panel.focus(), Some(SettingsTarget::Choice(at, _)) if at == row),
            "↓ out of a mark lands on an item, never on another row's ×: {:?}",
            panel.focus()
        );
        // **And the walk reaches the verb at the foot**, which is the other end
        // of the same claim: a door drawn below the last item that the arrows
        // stop one row above is a door the keyboard cannot open.
        panel.focus_to(SettingsTarget::Choice(row, row.option_count() - 1));
        panel.key(SettingsKey::Down, content, &values());
        assert_eq!(
            panel.focus(),
            Some(SettingsTarget::MenuAction(row)),
            "↓ off the last value lands on `Add scheme…`"
        );
        panel.key(SettingsKey::Up, content, &values());
        assert_eq!(
            panel.focus(),
            Some(SettingsTarget::Choice(row, row.option_count() - 1)),
            "and ↑ goes back into the list"
        );
    }

    /// PIN (user ruling 2026-08-19) — **the × leaves the list standing; the
    /// pencil and the verb take it away.**
    ///
    /// This picker stopped being only a picker the day the verbs moved onto it.
    /// Management comes in runs, and a reader tidying three schemes out of a
    /// folder would otherwise reopen the same menu three times, each reopen
    /// putting the list back under the pointer with the row they were aiming at
    /// next moved up by one. The other two close because what they open needs
    /// the room — both end with a file in a preview pane and this dialog gone.
    ///
    /// Red gate: `close_menu()` in the `MenuItemDelete` arm and the first
    /// assertion goes red; drop it from the other two and the third does.
    #[test]
    fn recycling_a_scheme_leaves_its_menu_open_and_the_other_two_verbs_close_it() {
        let files = scheme_file_lines();
        let rows = flat_rows();
        let lines = shortcut_lines();
        let content = SettingsContent {
            rows: &rows,
            shortcuts: &lines,
            profiles: &[],
            scheme_files: &files,
            advanced: every_group_open(),
            advanced_reveal: None,
            editor: None,
            values: Box::leak(Box::new(SettingsValues::sample())),
        };
        let row = SettingsRow::DarkScheme;
        let mine = (0..row.option_count())
            .find(|index| menu_item_is_user_file(row, *index, content))
            .expect("the fixture holds a file of the reader's own");
        for (target, closes) in [
            (SettingsTarget::MenuItemDelete(row, mine), false),
            (SettingsTarget::MenuItemEdit(row, mine), true),
            (SettingsTarget::MenuAction(row), true),
        ] {
            let mut panel = SettingsPanel::default();
            panel.toggle(content);
            panel.select_category(SettingsCategory::Appearance);
            panel.press(SettingsTarget::Combo(row));
            panel.key(SettingsKey::Activate, content, &values());
            assert_eq!(panel.menu(), Some(row), "the picker is open to begin with");
            panel.focus_to(target);
            assert_eq!(
                panel.key(SettingsKey::Activate, content, &values()),
                SettingsKeyVerdict::Chose(target),
                "{target:?} is the runtime's to run — it reaches a folder"
            );
            assert_eq!(
                panel.menu().is_none(),
                closes,
                "{target:?}: the list closing is {closes}"
            );
        }
        // And the pointer path agrees with the keyboard's, which is the rule
        // `apply_settings_choice` exists for.
        let mut panel = SettingsPanel::default();
        panel.toggle(content);
        panel.select_category(SettingsCategory::Appearance);
        panel.press(SettingsTarget::Combo(row));
        panel.key(SettingsKey::Activate, content, &values());
        panel.press(SettingsTarget::MenuItemDelete(row, mine));
        assert_eq!(
            panel.menu(),
            Some(row),
            "a press on a × leaves the menu it was pressed in"
        );
        assert_eq!(
            panel.focus(),
            Some(SettingsTarget::Choice(row, mine.saturating_sub(1))),
            "and the ring steps one row up, onto a row that is still there"
        );
    }

    /// PIN (§7.1.6c-4c) — **a picker re-lists when the catalogue's revision
    /// moves, and not otherwise.**
    ///
    /// The mechanism 4a could not have: `option_label` hands back `&'static str`,
    /// so a list that can change has to be rebuilt into a *new* leak rather than
    /// mutated — and rebuilding on every call would leak per frame. The claim is
    /// therefore two-sided, and the second half is the one that matters for a
    /// dialog that redraws on hover.
    ///
    /// Red gate: drop the revision from the key and the "same pointer" assertion
    /// goes red; cache the first answer forever and the "new names" one does.
    #[test]
    fn a_pickers_list_is_rebuilt_exactly_when_the_catalogue_moves() {
        let slot = SchemeLabelSlot::new();
        let first = slot.get(1, || vec!["Folio Dark".to_owned(), "Nord".to_owned()]);
        assert_eq!(first, ["Folio Dark", "Nord"]);

        let again = slot.get(1, || panic!("the same revision must not rebuild"));
        assert_eq!(
            again.as_ptr(),
            first.as_ptr(),
            "one leak per revision, not one per ask"
        );

        let moved = slot.get(2, || {
            vec![
                "Folio Dark".to_owned(),
                "Nord".to_owned(),
                "Nord (custom)".to_owned(),
            ]
        });
        assert_eq!(moved, ["Folio Dark", "Nord", "Nord (custom)"]);
        assert_eq!(
            moved[0].as_ptr(),
            first[0].as_ptr(),
            "a name that was already there is the very same string: the interning              is what keeps a folder edited all afternoon from leaking a copy of              every unchanged name"
        );
    }

    /// PIN (user ruling 2026-08-17, amended 2026-08-18) — **`Advanced` is a
    /// page's own group: its rows are the seven the ruling leaves in it, they
    /// come last, and while it is collapsed they are nowhere.**
    ///
    /// The list is the ruling read literally and not a heuristic. The second
    /// half is `visible_rows`' own contiguity discipline one level down: the
    /// disclosure is derived by partitioning a page's rows, which produces the
    /// right stack only while the everyday rows come first.
    ///
    /// Red gate: file `Theme` as advanced and the first assertion goes red; move
    /// `Background image` above `Cursor` in `visible_rows` and the last does.
    #[test]
    fn every_page_puts_its_everyday_rows_above_its_advanced_ones() {
        assert_eq!(
            flat_rows()
                .into_iter()
                .filter(|row| row.advanced())
                .collect::<Vec<_>>(),
            [
                SettingsRow::BackgroundImage,
                SettingsRow::ImageFit,
                SettingsRow::ImageOpacity,
                SettingsRow::BackgroundOpacity,
                SettingsRow::Acrylic,
                SettingsRow::AlwaysOnTop,
                SettingsRow::SplitDirection,
                // DESIGN §2.6, 2026-08-19. Last in the group, and the only row in
                // the dialog that overrides a colour a program named — which is
                // the argument for it being under a disclosure rather than beside
                // the scheme pair it repairs.
                SettingsRow::MinimumContrast
            ],
            "the group the 2026-08-18 ruling leaves standing, plus the contrast floor"
        );
        // **`Sidebar` came back out** (user ruling 2026-08-18). It is an
        // everyday row again and it is back where it was born — directly under
        // the row it depends on, so the dependency is legible from the page and
        // not only from the condition.
        assert!(
            !SettingsRow::Sidebar.advanced(),
            "Sidebar is an everyday row again"
        );
        let railed = visible_rows(TabLayoutMode::Vertical);
        let at = railed
            .iter()
            .position(|row| *row == SettingsRow::Sidebar)
            .expect("a vertical tab layout grows the Sidebar row");
        // **The neighbour, and then the run** (§7.1.6c-4d 裁决一, put back
        // 2026-08-24). This read `railed[at.saturating_sub(3)..=at]` between
        // 2026-08-19 and 2026-08-24, on the argument that the group is the
        // adjacency the ruling was asking for — which let focus mode's two rows
        // wedge in between the pair, and the user found the gap on the machine.
        // The ruling's words are 紧贴, so the distance is one; the rest of the
        // "what shape is this window" group follows the pair instead of
        // splitting it.
        assert_eq!(
            &railed[at - 1..=at],
            &[SettingsRow::TabLayout, SettingsRow::Sidebar],
            "and it stands on the foot of the row that conditions it"
        );
        assert_eq!(
            &railed[at + 1..=at + 2],
            &[SettingsRow::FocusMode, SettingsRow::FocusCardHeight],
            "the two unconditional rows of the same question follow the pair — \
             `Focus card height` under the row that turns the mode on"
        );
        assert!(
            !SettingsRow::PsReadLine.advanced(),
            "the PSReadLine row repairs something the reader has already watched \
             go wrong, so it is the last row in the dialog that may be hidden"
        );
        for layout in [TabLayoutMode::Horizontal, TabLayoutMode::Vertical] {
            let rows = visible_rows(layout);
            for category in SettingsCategory::ALL {
                let page: Vec<SettingsRow> = rows
                    .iter()
                    .copied()
                    .filter(|row| row.category() == category)
                    .collect();
                let first_advanced = page.iter().position(|row| row.advanced());
                if let Some(at) = first_advanced {
                    assert!(
                        page[at..].iter().all(|row| row.advanced()),
                        "{category:?} ({layout:?}): an everyday row is filed \
                         below an advanced one, so the disclosure would either \
                         hide it or leave a gap: {page:?}"
                    );
                }
            }
        }
    }

    // ── the disclosure's own two hundred milliseconds ────────────────────────

    /// `PAGE` with its group in a named state, a named reveal on it, and the
    /// page scrolled this far down.
    ///
    /// It goes through `content_with` and then writes the one field, rather than
    /// spelling a whole `SettingsContent` out: every other answer this fixture
    /// gives has to be the answer the rest of the module's claims are stated
    /// against, or a difference in the reveal would be reading as a difference in
    /// something else.
    fn revealed(
        advanced: AdvancedOpen,
        reveal: Option<(SettingsCategory, f32)>,
        scroll: f32,
    ) -> SettingsLayout {
        let rows = flat_rows();
        let lines = shortcut_lines();
        let mut content = content_with(&rows, &lines, advanced);
        content.advanced_reveal = reveal;
        layout_for_menu(
            SURFACE.0,
            SURFACE.1,
            1.0,
            None,
            None,
            content,
            PAGE,
            scroll,
            MENU_UNSCROLLED,
            &mut measure,
        )
        .expect("this window hosts the dialog")
    }

    /// The one page in the dialog that has something **under** its Advanced
    /// group — the profile editor, whose foot closes the page below the group's
    /// last row — with a named reveal on it.
    fn editor_revealed(
        subject: EditorSubject,
        reveal: Option<(SettingsCategory, f32)>,
    ) -> SettingsLayout {
        editor_revealed_scrolled(subject, reveal, UNSCROLLED)
    }

    /// The same, scrolled this far down — which the claims about the group's
    /// lower rows need, because the editor is taller than the dialog's cap.
    fn editor_revealed_scrolled(
        subject: EditorSubject,
        reveal: Option<(SettingsCategory, f32)>,
        scroll: f32,
    ) -> SettingsLayout {
        let rows = visible_rows(TabLayoutMode::Vertical);
        let lines = profile_lines();
        let mut content = editing_content(&rows, &lines, subject);
        content.advanced_reveal = reveal;
        layout_for_menu(
            SURFACE.0,
            SURFACE.1,
            1.0,
            None,
            None,
            content,
            SettingsCategory::Profiles,
            scroll,
            MENU_UNSCROLLED,
            &mut flat(0.0),
        )
        .expect("this window can host the dialog")
    }

    /// Every advanced row `PAGE` holds, in the order the group stacks them.
    fn advanced_rows_of_page() -> Vec<SettingsRow> {
        flat_rows()
            .into_iter()
            .filter(|row| row.category() == PAGE && row.advanced())
            .collect()
    }

    /// The height of `PAGE`'s open group — the header's foot down to the foot of
    /// the verb that closes it, which is the number a reveal's `t` is a fraction
    /// of.
    fn open_group_span(open: &SettingsLayout) -> f32 {
        let header = open.advanced().expect("the page has a disclosure");
        let verb = open.reset_advanced().expect("an open group has its verb");
        verb[3] - header.band[3]
    }

    /// PIN (animation block, second slice) — **`None` is today's dialog, to the
    /// pixel, and a reveal that has landed is the same dialog again.**
    ///
    /// This is the reduced-motion red line stated where it is actually paid.
    /// A window whose reader has asked for less motion passes no clock at all, so
    /// the whole of what that reader gets is the first frame at its final value:
    /// the same group in the same place with the same rows and the same verb, no
    /// band cut out of anything, and nothing to wake the window for. The
    /// animation is a layer of gain over a state that was already legible
    /// without it — `wait_halo_opacity`'s own paradigm — and the way to prove it
    /// is a layer is to take it away and find the page unchanged.
    ///
    /// Red gate: make `advanced_reveal_of` answer `Some(0.5)` where it answers
    /// `None` and every assertion here goes red at once; make it answer
    /// `Some(0.999)` for a landed reveal and the third does.
    #[test]
    fn a_group_with_no_clock_on_it_is_exactly_the_group_the_bool_describes() {
        let shut = revealed(AdvancedOpen::default(), None, UNSCROLLED);
        let open = revealed(every_group_open(), None, UNSCROLLED);
        assert_eq!(
            (shut.advanced_clip(), open.advanced_clip()),
            (None, None),
            "with no clock on it there is no band to cut anything to"
        );
        for row in advanced_rows_of_page() {
            assert!(
                shut.row(row).is_none(),
                "{row:?} is placed inside a group that is shut and unmoving"
            );
            assert!(
                open.row(row).is_some(),
                "{row:?} is missing from a group that is open and unmoving"
            );
        }
        assert_eq!(shut.reset_advanced(), None);
        assert!(open.reset_advanced().is_some());

        // **And a reveal that has landed is that same page**, whole and not
        // merely equivalent: the clock's last frame has to be the frame the
        // clock is then taken off, or the group would settle with a visible
        // step in it.
        let landed = revealed(every_group_open(), Some((PAGE, 1.0)), UNSCROLLED);
        assert_eq!(
            landed, open,
            "a reveal at its end is the open page it is easing towards, band and \
             all"
        );
        // A clock on a *different* page is no clock on this one, which is what
        // makes the field a fact about one group rather than about the dialog.
        let elsewhere = revealed(
            every_group_open(),
            Some((SettingsCategory::Profiles, 0.25)),
            UNSCROLLED,
        );
        assert_eq!(
            elsewhere, open,
            "a reveal names the page it is easing, and bears on no other"
        );
        // The keyboard's own copy of the same sentence.
        let rows = flat_rows();
        let lines = shortcut_lines();
        let mut content = content_with(&rows, &lines, every_group_open());
        let settled = focus_order(content, PAGE);
        content.advanced_reveal = Some((PAGE, 1.0));
        assert_eq!(
            focus_order(content, PAGE),
            settled,
            "and the Tab order it lands on is the Tab order it would have had \
             with no clock at all"
        );
    }

    /// RED (animation block, second slice) — **a half-open group stands where an
    /// open group stands, and half a band is opened onto it.**
    ///
    /// The whole mechanism in one claim. The rows do not slide in, they do not
    /// squash and they do not grow: they are laid out at the places and at the
    /// heights an open group gives them, and what moves is the edge of the
    /// window they are seen through. That is `clip_content`'s own law — *geometry
    /// translates, only drawing is cut* — one box further in, and it is the
    /// reason a row caught mid-reveal is the top half of a whole row rather than
    /// a squat one.
    ///
    /// Red gate: place the group's rows from the reveal (advance the cursor by
    /// `t ×` each band) and the first loop goes red; drop the `- folded` from
    /// `advance`'s caller and the height claim does; start the band on the
    /// disclosure's *top* rather than its foot and the third does.
    #[test]
    fn half_a_reveal_leaves_every_row_where_it_stands_and_opens_half_a_band() {
        let open = revealed(every_group_open(), None, UNSCROLLED);
        let half = revealed(every_group_open(), Some((PAGE, 0.5)), UNSCROLLED);
        assert_eq!(
            half.frame, open.frame,
            "the dialog does not change shape while a group inside it opens"
        );
        // Every band of the page, the group's own included, is where an open
        // group puts it.
        for row in flat_rows().into_iter().filter(|row| row.category() == PAGE) {
            assert_eq!(
                half.row(row).map(|placed| placed.band),
                open.row(row).map(|placed| placed.band),
                "{row:?} moved while the band over it was opening"
            );
        }
        assert_eq!(
            half.advanced().map(|group| group.band),
            open.advanced().map(|group| group.band),
            "the header is the page's, not the group's: it does not move"
        );
        assert_eq!(
            half.reset_advanced(),
            open.reset_advanced(),
            "and neither does the verb that closes the group"
        );

        let span = open_group_span(&open);
        let band = half
            .advanced_clip()
            .expect("a reveal in flight opens a band");
        assert_eq!(
            band[1],
            open.advanced().expect("the page has a disclosure").band[3],
            "the band grows downwards from the header's own foot"
        );
        assert!(
            (band[3] - band[1] - span / 2.0).abs() < 0.5,
            "half the group's height is showing: {} of {span}",
            band[3] - band[1]
        );
        assert!(
            ((open.max_scroll() - half.max_scroll()) - span / 2.0).abs() < 0.5,
            "and the page is exactly the other half shorter: {} against {}",
            open.max_scroll(),
            half.max_scroll()
        );
    }

    /// RED (animation block, second slice) — **what stands under a half-open
    /// group stands on the bottom of its band.**
    ///
    /// The other half of the mechanism, and the only page in the dialog that can
    /// state it: every other Advanced group ends its page, so the lift has
    /// nothing to lift. The profile editor's foot is under one, and it comes up
    /// by exactly what is still folded away — not by a fraction of its own
    /// travel, and not on a curve of its own. One clock, one number, and the
    /// page below simply stands on the band's bottom edge.
    ///
    /// Red gate: lift the page by `folded` at the *disclosure* instead of at the
    /// group's last item and the foot lands a whole group too high; drop the
    /// lift and it lands a half-group too low.
    #[test]
    fn what_stands_under_a_half_open_group_stands_on_the_bottom_of_its_band() {
        let subject = editor_subject(true);
        let open = editor_revealed(subject, None);
        let half = editor_revealed(subject, Some((SettingsCategory::Profiles, 0.5)));
        let opened_foot = open.editor_foot.expect("the editor closes with a verb");
        let half_foot = half.editor_foot.expect("and it is there mid-reveal too");
        let band = half
            .advanced_clip()
            .expect("a reveal in flight opens a band");
        assert_eq!(
            half_foot[1],
            band[3] + FOOT_MARGIN_TOP_LOGICAL_PX,
            "the foot stands on the bottom of the band, one margin down"
        );
        let span = (opened_foot[1] - FOOT_MARGIN_TOP_LOGICAL_PX)
            - half.advanced().expect("the editor has a disclosure").band[3];
        assert!(
            ((opened_foot[1] - half_foot[1]) - span / 2.0).abs() < 0.5,
            "and it came up by the half that is still folded: {} of {span}",
            opened_foot[1] - half_foot[1]
        );
        // The rows above it did not come with it, which is what makes this a
        // reveal rather than a slide.
        for row in EDITOR_ROWS.into_iter().filter(|row| row.advanced()) {
            assert_eq!(
                half.row(row).map(|placed| placed.band),
                open.row(row).map(|placed| placed.band),
                "{row:?} moved while the band over it was opening"
            );
        }
    }

    /// RED (animation block, second slice) — **a group easing shut keeps its
    /// rows until the clock says they are gone, and a group that has only just
    /// begun to open has them and shows none of them.**
    ///
    /// [`AdvancedOpen`] goes false on the frame the disclosure is pressed — it is
    /// the answer to *what does this reader want*, and the reader wants it shut.
    /// So the rows cannot be the bool: a group whose rows left with the press
    /// would have nothing left to close, and the two hundred milliseconds after
    /// it would be a page that had already finished changing.
    ///
    /// **Zero is where the clock hands the group back to the bool.** At `t = 0`
    /// on the way out there is nothing of the group left to show, so the page is
    /// the shut page — every row gone, every pixel of height gone, and the frame
    /// the clock is taken off on identical to the frame after it. On the way *in*
    /// the same `t = 0` is a group the bool has already opened: its rows are
    /// placed, at their whole height, and the band opened onto them has none —
    /// which is the first frame of the reveal, and it looks exactly like the last
    /// frame of the close. The two ends meet, which is what keeps a group that is
    /// opened and shut again from stepping.
    ///
    /// Red gate: make `advanced_showing` the bool alone and the first loop goes
    /// red; make it `is_some()` rather than `> 0.0` and the closed-at-zero page
    /// stops being the shut page; drop the `- folded` and the opening page
    /// reserves a whole group for a band with no height — which is what the last
    /// loop then finds drawn, because a page that reserved the room would have
    /// scrolled to it. (The band's own cut is not what that loop catches at zero:
    /// the page's clip and the band agree there. It is pinned where they can
    /// disagree, in `a_row_the_reveal_has_half_uncovered_…`.)
    #[test]
    fn a_group_easing_shut_keeps_its_rows_until_the_clock_says_they_are_gone() {
        let closing = revealed(AdvancedOpen::default(), Some((PAGE, 0.4)), UNSCROLLED);
        for row in advanced_rows_of_page() {
            assert!(
                closing.row(row).is_some(),
                "{row:?} left on the press instead of on the clock, and the close \
                 has nothing to close"
            );
        }
        assert!(
            closing.reset_advanced().is_some(),
            "and so does the verb that closes the group"
        );
        assert!(
            closing.advanced_clip().is_some(),
            "and there is a band for them to be leaving through"
        );

        // The close's last frame **is** the shut page, whole and not merely
        // equivalent: it is the frame the clock is taken off on.
        let shut = revealed(AdvancedOpen::default(), None, UNSCROLLED);
        let gone = revealed(AdvancedOpen::default(), Some((PAGE, 0.0)), UNSCROLLED);
        assert_eq!(
            gone, shut,
            "a group showing none of itself with the bool already false is the \
             shut page, and there is nothing left for the clock to say"
        );
        for row in advanced_rows_of_page() {
            assert!(
                shut.row(row).is_none(),
                "{row:?} is placed inside a group nobody is opening"
            );
        }
        assert_eq!(shut.advanced_clip(), None);

        // And the open's *first* frame: the rows are there, the band is not.
        let opening = revealed(every_group_open(), Some((PAGE, 0.0)), UNSCROLLED);
        let band = opening
            .advanced_clip()
            .expect("a group the bool has opened has a band, even an empty one");
        assert_eq!(
            band[3], band[1],
            "and on the first frame that band has no height at all"
        );
        for row in advanced_rows_of_page() {
            assert!(
                opening.row(row).is_some(),
                "{row:?} is missing from a group that is opening"
            );
        }
        assert!(
            (opening.max_scroll() - shut.max_scroll()).abs() < 0.5,
            "a band with no height reserves no height: {} against {}",
            opening.max_scroll(),
            shut.max_scroll()
        );

        // **And none of it is drawn**, which is the half a placed row could
        // still have got wrong: the rows are in the layout, so the only thing
        // keeping them off the glass is the band they are cut to.
        let at_group = revealed(
            every_group_open(),
            Some((PAGE, 0.0)),
            scroll_showing(&shut, shut.advanced().expect("a disclosure").band),
        );
        let drawn = labels_of(&at_group, None, &values());
        for row in advanced_rows_of_page() {
            assert!(
                !drawn.iter().any(|label| label.text == row.title()),
                "{row:?} is drawn inside a band with no height"
            );
        }
        assert!(
            !drawn
                .iter()
                .any(|label| label.text == Text::ResetAdvanced.text()),
            "and so is the verb"
        );
    }

    /// RED (animation block, second slice; the law of 2026-08-26) — **a row the
    /// reveal has only half uncovered answers no press and takes no ring.**
    ///
    /// **What can be pressed is what can be seen.** A row sliced by the band's
    /// own edge is a picture of a row: the eye cannot tell which row it is aiming
    /// at, and a press it took would be a press aimed at something else. This is
    /// the law the house wrote on 2026-08-26 after a layout probe pressed a
    /// button nobody could see and tore the files column out into a float — the
    /// drawn and the pressable are one derivation — and a band that is opening is
    /// exactly the case that can put them out of step.
    ///
    /// **Stated on the profile editor**, which is the one page in this dialog
    /// with something under its Advanced group. Everywhere else the group ends
    /// the page, so at the foot of the scroll the band's bottom edge and the
    /// scrollport's are the same line and `shows` already refuses everything
    /// `reveals` would: the rule is right there too and cannot be caught there.
    /// Here the editor's own verb holds the two edges apart, and it is the band's
    /// that has to answer.
    ///
    /// The keyboard answers the same question from the content alone, because
    /// `SettingsPanel::key` has no layout to read: while a clock is on the group,
    /// nothing the group holds is a stop at all. That refuses every band the
    /// geometry refuses and a few it would have allowed, which is the safe side
    /// of a rule about what may be acted on.
    ///
    /// Red gate: drop the `reveals` guard from the rows loop in `hit` and the
    /// sliced row answers with its own field; drop the `settled` filter in
    /// `page_order` and the Tab order holds rows nobody can press; stop cutting
    /// the row ink and the sliced row's title is drawn to its own full box.
    #[test]
    fn a_row_the_reveal_has_half_uncovered_answers_no_press_and_takes_no_ring() {
        let subject = editor_subject(true);
        let open = editor_revealed(subject, None);
        let header = open.advanced().expect("the editor has a disclosure");
        let foot = open.editor_foot.expect("the editor closes with a verb");
        let span = (foot[1] - FOOT_MARGIN_TOP_LOGICAL_PX) - header.band[3];
        // The reveal that stops **halfway down the last row of the group**, so
        // that one row is cut by the band's edge and the ones above it are whole.
        let cut = SettingsRow::ProfileIntegration;
        let whole = SettingsRow::ProfileHyperlink;
        let target = {
            let band = open.row(cut).expect("the group holds its rows").band;
            (band[1] + band[3]) / 2.0
        };
        let fraction = (target - header.band[3]) / span;
        let reveal = Some((SettingsCategory::Profiles, fraction));
        let unscrolled = editor_revealed(subject, reveal);
        let half = editor_revealed_scrolled(subject, reveal, unscrolled.max_scroll());
        let band = half
            .advanced_clip()
            .expect("a reveal in flight opens a band");

        let sliced = half.row(cut).expect("the group holds its rows").band;
        assert!(
            half.shows(sliced),
            "{cut:?} is wholly inside the scrollport, so the scrollport is not \
             what refuses it"
        );
        assert!(
            !within(sliced, band) && sliced[1] < band[3],
            "and it is cut by the band's own edge: {sliced:?} against {band:?}"
        );
        let uncovered = half.row(whole).expect("the group holds its rows").band;
        assert!(
            half.shows(uncovered) && within(uncovered, band),
            "{whole:?} is wholly uncovered and wholly on screen"
        );

        let (x, y) = centre(combo_of(&half, whole));
        assert_eq!(
            hit(&half, &editing_values(subject), x, y),
            whole.control_target(),
            "{whole:?} is wholly uncovered and still answers its own press"
        );
        let (x, y) = centre(combo_of(&half, cut));
        assert_eq!(
            hit(&half, &editing_values(subject), x, y),
            SettingsTarget::Panel,
            "{cut:?} is cut by the band's edge and must be a picture, not a button"
        );

        // **And the ink is cut where the press is.** The sliced row is drawn —
        // half of it is what the reader can see — but only as far as the band,
        // so what answers no press is exactly what cannot be read.
        let drawn = labels_of(&half, None, &editing_values(subject));
        let title = drawn
            .iter()
            .find(|label| label.text == cut.title())
            .expect("the sliced row's title is on the visible half of it");
        assert!(
            title.clip.is_some_and(|window| window[3] <= band[3] + 0.01),
            "the sliced row is drawn past the band that opens onto it: {title:?}"
        );

        // The keyboard, from the content alone — stated on `PAGE`, because this
        // list is a fact about the content and every page's group answers it the
        // same way.
        let rows = flat_rows();
        let lines = shortcut_lines();
        let mut content = content_with(&rows, &lines, every_group_open());
        content.advanced_reveal = Some((PAGE, 0.5));
        let order = focus_order(content, PAGE);
        for row in advanced_rows_of_page() {
            assert!(
                !order.contains(&row.control_target()),
                "{row:?} is a Tab stop while the band over it is still moving"
            );
        }
        assert!(
            !order.contains(&SettingsTarget::ResetAdvanced(PAGE)),
            "and so is the verb"
        );
        assert!(
            order.contains(&SettingsTarget::Advanced(PAGE)),
            "the disclosure itself is not inside the group and stays reachable — \
             it is how the reader turns the group back"
        );
    }

    /// PIN (animation block, second slice) — **the page is as tall as the part
    /// of the group that is showing, on every frame of the way.**
    ///
    /// One subtraction, read by the height, by `max_scroll` and by the placement
    /// walk alike. `page_items` is read twice in this module and held in
    /// agreement by being the same call; the reveal is the second thing both
    /// readings have to agree about, so it is the same call too. Measured one way
    /// and placed another, the bar down the side would spend two hundred
    /// milliseconds pointing at a height nothing occupies — the classic shape of
    /// "one gesture, two geometries".
    ///
    /// Red gate: leave `page_height` reading the whole stack and the ladder goes
    /// red at the first step; measure the folded part from a second walk of
    /// `page_items` taken before the reveal was applied and the last claim does.
    #[test]
    fn the_page_is_as_tall_as_the_part_of_the_group_that_is_showing() {
        let open = revealed(every_group_open(), None, UNSCROLLED);
        let span = open_group_span(&open);
        let shut = revealed(AdvancedOpen::default(), None, UNSCROLLED);
        for step in 0..=4 {
            let fraction = step as f32 / 4.0;
            let easing = revealed(every_group_open(), Some((PAGE, fraction)), UNSCROLLED);
            assert!(
                ((easing.max_scroll() - shut.max_scroll()) - fraction * span).abs() < 0.5,
                "at {fraction} the page carries {} of the group's {span}",
                easing.max_scroll() - shut.max_scroll()
            );
            // The bar and the band are the same number, which is the whole of
            // why the bar cannot point at nothing.
            let shown = easing
                .advanced_clip()
                .map_or(span, |band| band[3] - band[1]);
            assert!(
                (shown - fraction * span).abs() < 0.5,
                "and the band over it shows {shown} of the same {span}"
            );
        }
    }

    /// PIN (§7.1.6c-4d 裁决一, user ruling 2026-08-18; put back 2026-08-24) —
    /// **`Sidebar` is the row directly under `Tab layout`, with nothing wedged
    /// between them.**
    ///
    /// The ruling's own words are "紧贴 `Tab layout` 之下", and its reason is a
    /// reader's sentence rather than a taxonomy: someone has just chosen
    /// `Vertical` and is asking what that rail looks like, so the answer may not
    /// be one row further down for every row a later slice thinks of. A run of
    /// four is not the adjacency that ruling bought — `Focus mode` and `Focus
    /// card height` landed between the two on 2026-08-19 and 2026-08-21 without
    /// anyone restating it, and the user found the gap on the machine.
    ///
    /// Stated as an index and not as a slice, because the claim is exactly the
    /// distance: one. What may follow the pair is the next test's business.
    ///
    /// Red gate: push `Sidebar` after either focus row — which is where it stood
    /// until this was written — and the arithmetic goes red naming the distance
    /// it found.
    #[test]
    fn the_sidebar_row_stands_directly_under_the_row_that_conditions_it() {
        let railed = visible_rows(TabLayoutMode::Vertical);
        let tab_layout = railed
            .iter()
            .position(|row| *row == SettingsRow::TabLayout)
            .expect("the dialog asks where the tabs go");
        let sidebar = railed
            .iter()
            .position(|row| *row == SettingsRow::Sidebar)
            .expect("a vertical tab layout grows the Sidebar row");
        assert_eq!(
            sidebar,
            tab_layout + 1,
            "the conditional row stands on the foot of the row that conditions \
             it: a reader who just chose `Vertical` reads the answer to \"what \
             does that rail look like\" on the very next line, not past whatever \
             unconditional rows a later slice filed under `Tab layout`"
        );
    }

    /// PIN (user ruling 2026-08-17) — **a collapsed group costs no band, no
    /// ring, no ink and no hit target; expanding it adds its rows and one
    /// `Reset to defaults`.**
    ///
    /// The conditional Sidebar row's own four-way discipline, applied to eight
    /// rows at once: a row taught the condition in one place and not the others
    /// is a control you can click and cannot see.
    ///
    /// Red gate: filter the advanced rows out of `page_rows` and leave them in
    /// `page_items` and the "no gap" assertion goes red; leave `Reset` in the
    /// item list while the group is shut and the focus-order one does.
    #[test]
    fn a_collapsed_advanced_group_costs_nothing_and_opening_it_adds_its_rows_and_its_verb() {
        let shut = shaped(SettingsCategory::Appearance, AdvancedOpen::default(), None);
        let open = shaped(SettingsCategory::Appearance, every_group_open(), None);

        let group = shut.advanced().expect("the page has a disclosure");
        assert!(!group.open, "and it is shut");
        assert_eq!(group.group, SettingsCategory::Appearance);
        assert_eq!(
            shut.reset_advanced(),
            None,
            "a verb inside a collapsed group is a verb nobody can see"
        );
        for row in flat_rows().into_iter().filter(|row| row.advanced()) {
            assert!(
                shut.row(row).is_none(),
                "{row:?} is placed inside a group that is shut"
            );
        }
        // No gap: the disclosure sits directly under the last everyday row, one
        // row height down, and nothing is reserved for what is hidden.
        let last_everyday = shut.rows.last().expect("the page has everyday rows");
        assert_eq!(
            group.band[1], last_everyday.band[3],
            "the heading follows the last row it is under, with no room left for \
             the rows it is hiding"
        );
        assert!(
            shut.max_scroll() <= open.max_scroll(),
            "and a shut group is never the taller page"
        );

        // Nowhere in the window answers for a hidden row.
        let mut y = 0.0_f32;
        while y < SURFACE.1 {
            let mut x = 0.0_f32;
            while x < SURFACE.0 {
                let target = hit(&shut, &values(), f64::from(x), f64::from(y));
                assert!(
                    !matches!(
                        target,
                        SettingsTarget::Combo(row) | SettingsTarget::Slider(row)
                            if row.advanced()
                    ),
                    "({x}, {y}) answers {target:?} for a row inside a shut group"
                );
                assert_ne!(
                    target,
                    SettingsTarget::ResetAdvanced(SettingsCategory::Appearance),
                    "({x}, {y}) answers for a verb inside a shut group"
                );
                x += 7.0;
            }
            y += 7.0;
        }
        let labels = labels_of(&shut, None, &values());
        for absent in flat_rows().into_iter().filter(|row| row.advanced()) {
            assert!(
                !labels.iter().any(|label| label.text == absent.title()),
                "{absent:?} is drawn inside a group that is shut"
            );
        }
        // **The heading itself is drawn — scrolled to, since 2026-08-21.** The
        // everyday Appearance rows now fill the capped dialog on their own (the
        // card-height row carried the page over 600), so the folded heading sits
        // just below the fold: the way back is a scroll away rather than in view,
        // which is exactly the case `DIALOG_MAX_HEIGHT_LOGICAL_PX` rules for.
        let at_heading = shaped_scrolled(
            SettingsCategory::Appearance,
            AdvancedOpen::default(),
            None,
            scroll_showing(&shut, group.band),
        );
        assert!(
            labels_of(&at_heading, None, &values())
                .iter()
                .any(|label| label.text == Text::AdvancedGroup.text()),
            "but the heading itself is drawn once scrolled to, or there would be \
             no way back"
        );

        // Opened: the rows are there, the verb is there, and the triangle says so.
        let group = open.advanced().expect("the page has a disclosure");
        assert!(group.open);
        let reset = open.reset_advanced().expect("an open group has its verb");
        let last = open.rows.last().expect("the page has rows");
        assert!(
            last.row.advanced() && reset[1] > last.band[3],
            "the verb closes the group, under the last row inside it"
        );
        assert_eq!(
            width(reset),
            RESET_ADVANCED_WIDTH_LOGICAL_PX,
            "and it is the shortcut page's `.btn` at its own width"
        );
        // The two hit tests are asked where the two boxes are on screen: opening
        // the group takes the page past the dialog's 600px cap, so the verb that
        // closes it is below the fold until a reader scrolls down to it — and
        // since 2026-08-21 the folded heading is a scroll away too, because the
        // everyday rows above it now fill the capped dialog on their own.
        let at_foot = shaped_scrolled(
            SettingsCategory::Appearance,
            every_group_open(),
            None,
            open.max_scroll(),
        );
        let (x, y) = centre(
            at_foot
                .reset_advanced()
                .expect("the verb is still there at the foot of the page"),
        );
        assert_eq!(
            hit(&at_foot, &values(), x, y),
            SettingsTarget::ResetAdvanced(SettingsCategory::Appearance),
            "which answers for the page it closes"
        );
        // Scrolled to the heading (see `at_heading` above): its whole band turns
        // the group, not the 10×6 chevron alone.
        let heading = at_heading
            .advanced()
            .expect("the folded page still has its disclosure")
            .band;
        let (x, y) = centre(heading);
        assert_eq!(
            hit(&at_heading, &values(), x, y),
            SettingsTarget::Advanced(SettingsCategory::Appearance),
            "and the heading's whole band turns it, not the 10×6 chevron alone"
        );
        // **A chevron and no longer a triangle** (user ruling 2026-08-19, the
        // hybrid): the mark left the head of the row for its foot, and it turns
        // over rather than swapping glyphs — this file's own ruling for the
        // preview head's chevron and the tab strip's. Scrolled to the heading
        // since 2026-08-21, because its chevron sits below the fold now that the
        // everyday rows fill the capped dialog on their own.
        let open_at_heading = shaped_scrolled(
            SettingsCategory::Appearance,
            every_group_open(),
            None,
            scroll_showing(
                &open,
                open.advanced()
                    .expect("the open page has its disclosure")
                    .band,
            ),
        );
        let sprites = sprites_of(&open_at_heading, None, &values());
        let turned: Vec<ChromeMark> = sprites
            .iter()
            .map(|sprite| sprite.mark)
            .filter(|mark| matches!(mark, ChromeMark::Chevron { .. }))
            .collect();
        assert_eq!(
            turned,
            vec![ChromeMark::chevron(1.0)],
            "one chevron, fully over — and no second kind of disclosure"
        );
        assert!(
            !sprites
                .iter()
                .any(|sprite| matches!(sprite.mark, ChromeMark::TreeDisclosure { .. })),
            "the files tree's triangle is the files tree's, and this dialog no \
             longer borrows it"
        );
        let shut_sprites = sprites_of(&at_heading, None, &values());
        assert!(
            shut_sprites
                .iter()
                .any(|sprite| sprite.mark == ChromeMark::chevron(0.0)),
            "and the same chevron at rest while it is shut"
        );
    }

    /// PIN (user ruling 2026-08-17) — **the disclosure is a keyboard stop and
    /// Enter turns it.**
    ///
    /// A heading with a control in it that only the pointer can work would be
    /// the one control in this dialog the keyboard cannot reach — and it is the
    /// control that decides whether eight others are reachable at all.
    ///
    /// The verdict is `Chose` rather than a state change here, because turning
    /// it writes `settings.json`: `advanced_open` is persisted, and this type
    /// has no way to reach a file.
    #[test]
    fn enter_on_the_disclosure_asks_the_runtime_to_turn_it() {
        let rows = flat_rows();
        let lines = shortcut_lines();
        let shut = content_with(&rows, &lines, AdvancedOpen::default());
        let mut panel = SettingsPanel::default();
        panel.toggle(shut);
        panel.select_category(SettingsCategory::Appearance);
        let order = focus_order(shut, SettingsCategory::Appearance);
        let at = order
            .iter()
            .position(|stop| *stop == SettingsTarget::Advanced(SettingsCategory::Appearance))
            .expect("the disclosure is in the Tab order");
        assert_eq!(
            at,
            order.len() - 1,
            "and it is the last stop on a page whose group is shut"
        );
        panel.press(SettingsTarget::Advanced(SettingsCategory::Appearance));
        assert_eq!(
            panel.key(SettingsKey::Activate, shut, &values()),
            SettingsKeyVerdict::Chose(SettingsTarget::Advanced(SettingsCategory::Appearance)),
            "Enter asks for the same thing a press on it asks for"
        );
        panel.press(SettingsTarget::ResetAdvanced(SettingsCategory::Appearance));
        let open = content_with(&rows, &lines, every_group_open());
        assert_eq!(
            panel.key(SettingsKey::Activate, open, &values()),
            SettingsKeyVerdict::Chose(SettingsTarget::ResetAdvanced(SettingsCategory::Appearance)),
            "and so does its Reset"
        );
    }

    /// PIN (§7.1.6c-5, schema v11) — **the disclosure's stored shape survives a
    /// round trip, and a page this build has retired is dropped rather than
    /// taking a page with it.**
    ///
    /// §5.4 逐叶降级 for a list-valued field: the unknown key is discarded and
    /// every key beside it is honoured. The order the keys come back in is the
    /// rail's and not the file's, which is what keeps two files describing the
    /// same state from differing byte for byte.
    #[test]
    fn the_open_groups_are_written_as_page_keys_and_an_unknown_one_is_dropped() {
        let mut open = AdvancedOpen::default();
        assert_eq!(
            open.keys(),
            Vec::<String>::new(),
            "a fresh install writes []"
        );
        assert!(open.set(SettingsCategory::Appearance, true));
        assert!(
            !open.set(SettingsCategory::Appearance, true),
            "setting what is already set changes nothing"
        );
        assert!(open.set(SettingsCategory::General, true));
        assert_eq!(
            open.keys(),
            vec!["general".to_owned(), "appearance".to_owned()],
            "in the rail's order, not the order they were opened"
        );
        let read_back =
            AdvancedOpen::from_keys(["appearance", "a-page-this-build-retired", "general"]);
        assert_eq!(
            read_back, open,
            "an unknown key costs the known ones nothing"
        );
        for category in SettingsCategory::ALL {
            assert_eq!(
                SettingsCategory::from_key(category.key()),
                Some(category),
                "{category:?}'s key names it back"
            );
        }
        let mut turned = AdvancedOpen::default();
        turned.toggle(SettingsCategory::Appearance);
        assert!(turned.is_open(SettingsCategory::Appearance));
        turned.toggle(SettingsCategory::Appearance);
        assert!(!turned.is_open(SettingsCategory::Appearance));
    }

    /// PIN (mock-up geometry): the dialog lands exactly where
    /// `design/ui-mockup.html` puts it — `width: min(480px, 92%)`,
    /// `margin: 54px auto 0`, and a height its own content decides.
    ///
    /// The height is not a guess: it is `1 + 56 + content + 1` — two hairlines,
    /// the header's `16 + 30 + 10`, and a content box of
    /// `2 + 10 + 13 + 2 + rows * (11 + 32 + 11) + 18`, plus `16 + 13 + 2` for
    /// every heading after the first. The mock-up's own renderer reported 211 for
    /// the two rows under one heading this dialog first shipped with, which is
    /// [`dialog_height`] at `(2, 1)` and the number the formula is anchored on.
    ///
    /// Red gate: every term is load-bearing. Drop the `auto` centring and `left`
    /// moves; drop the 54 and `top` moves; use the row's *border* box (55, which
    /// is what it measures when it is not the last child) and every height here
    /// is one pixel per row too big.
    #[test]
    fn the_dialog_lands_where_the_mock_up_puts_it() {
        assert_eq!(
            dialog_height(2),
            219.0,
            "the mock-up's own measurement of two rows under one heading — 211 \
             when `.content` had 2px of top padding, and eight more since \
             §7.1.6c-5 gave the scrollport an inset a scrolled row can \
             disappear under"
        );
        let placed = open(1.0, false);
        assert_eq!(width(placed.frame), 720.0, "min(720px, 92%) at 1280 wide");
        assert_eq!(
            placed.frame[1],
            optical_top(SURFACE.1, height(placed.frame)),
            "and the drop is `minmax(54px, 2fr)` and not the old flat 54: two \
             parts of the window's slack above, three below"
        );
        assert_eq!(
            placed.frame[0],
            (SURFACE.0 - 720.0) / 2.0,
            "margin-left/right: auto"
        );
        assert_eq!(
            height(placed.frame),
            fixed_dialog_height(TabLayoutMode::Horizontal),
            "the tallest page decides the height, its one heading and its \
             Advanced group included — under the everyday cap, which on this \
             window is the bound that answers"
        );

        // The 92% share takes over below 720/0.92 ~= 782.6 logical pixels.
        let rows = flat_rows();
        let narrow = layout_for_menu(
            720.0,
            800.0,
            1.0,
            None,
            None,
            content(&rows, &[]),
            PAGE,
            UNSCROLLED,
            MENU_UNSCROLLED,
            &mut flat(0.0),
        )
        .expect("720 wide still hosts the dialog");
        assert_eq!(
            width(narrow.frame),
            (720.0_f32 * DIALOG_WIDTH_RATIO).round(),
            "under the cap the dialog takes 92% of the window"
        );
        assert_eq!(
            narrow.frame[0],
            ((720.0 - width(narrow.frame)) / 2.0).round()
        );
    }

    /// PIN (mock-up geometry): every control inside the dialog is the box the
    /// stylesheet gives it, at the offset the stylesheet puts it at.
    ///
    /// Read against the mock-up's own measurements, taken with the dialog open
    /// at 1280x800: `.dlg-close` 30x30 with its icon ending 22 from the dialog's
    /// edge, `.combo > button` 118x27.5 flush with the content's right padding,
    /// `.row .text` one gap to its left.
    #[test]
    fn every_control_is_the_box_the_stylesheet_gives_it() {
        let placed = open(1.0, false);
        let theme = row_of(&placed, SettingsRow::Theme);
        let cursor = row_of(&placed, SettingsRow::Cursor);
        assert_eq!((width(placed.close), height(placed.close)), (30.0, 30.0));
        assert_eq!(
            placed.frame[2] - placed.close[2],
            1.0 + HEADER_PADDING_RIGHT_LOGICAL_PX,
            "the 30px button ends 12 inside the dialog's hairline, so its 10px \
             icon ends 22 from the edge - the mock-up's own reasoning"
        );
        assert_eq!(
            placed.close[1],
            placed.frame[1] + 1.0 + 16.0,
            "padding-top: 16px"
        );

        assert_eq!(width(theme.combo), 118.0, "min-width: 118px");
        assert_eq!(height(theme.combo), 27.5, "5 + 15.5 + 5 + two borders");
        assert_eq!(
            placed.frame[2] - theme.combo[2],
            1.0 + CONTENT_PADDING_X_LOGICAL_PX + ROW_PADDING_X_LOGICAL_PX,
            "the control is flush with the row's own right edge"
        );
        assert_eq!(
            theme.combo[0] - theme.title[2],
            ROW_GAP_LOGICAL_PX,
            ".row gap: 16px between the text column and the control"
        );
        // `align-items: center`: the 27.5 control is centred on the 32 the two
        // stacked lines take, not top-aligned with them.
        let text_axis = (theme.title[1] + theme.desc[3]) / 2.0;
        let combo_axis = (theme.combo[1] + theme.combo[3]) / 2.0;
        assert!(
            (text_axis - combo_axis).abs() <= 0.5,
            "the row's items share one axis: {text_axis} vs {combo_axis}"
        );
        assert_eq!(
            theme.desc[1] - theme.title[3],
            ROW_DESC_MARGIN_TOP_LOGICAL_PX,
            ".desc margin-top: 1px"
        );
        assert_eq!(width(cursor.combo), width(theme.combo));
        assert_eq!(height(cursor.combo), height(theme.combo));
        assert_eq!(
            cursor.combo[1] - theme.combo[1],
            5.0 * ROW_HEIGHT,
            "Cursor is five identical rows under Theme — the two scheme rows \
             (§7.1.6c-4a) and the two font rows sit between them, and every one \
             of them is the same height. The window's ground used to be here \
             too; §7.1.6c-5's ruling moved its six rows under the disclosure"
        );
    }

    /// PIN (DPI): the dialog is one design at every scale — nothing collapses,
    /// nothing keeps a scale-1 size, and every box stays within a rounding pixel
    /// of the scaled design number.
    ///
    /// Red gate: a box built from an unscaled constant passes at 1.0 and fails
    /// at every other entry in this list.
    #[test]
    fn the_dialog_is_one_design_at_every_dpi() {
        for scale in [1.0_f32, 1.25, 1.5, 2.0] {
            let placed = open(scale, true);
            let near = |want: f32, got: f32, what: &str| {
                assert!(
                    (got - want).abs() <= 1.0,
                    "scale {scale}: {what} is {got}, wanted {want}"
                );
            };
            let combo = combo_of(&placed, SettingsRow::Theme);
            near(720.0 * scale, width(placed.frame), "the dialog's width");
            near(
                fixed_dialog_height(TabLayoutMode::Horizontal) * scale,
                height(placed.frame),
                "the dialog's height",
            );
            near(
                optical_top((SURFACE.1 * scale).round(), height(placed.frame)),
                placed.frame[1],
                "the dialog's drop",
            );
            near(30.0 * scale, width(placed.close), "the close button");
            near(30.0 * scale, height(placed.close), "the close button");
            near(118.0 * scale, width(combo), "the combo");
            near(27.5 * scale, height(combo), "the combo");
            let menu = placed.menu.expect("the menu is open");
            near(118.0 * scale, width(menu), "the menu");
            near(
                (2.0 + 8.0 + THEME_OPTIONS.len() as f32 * 27.5) * scale,
                height(menu),
                "the menu",
            );
            for item in &placed.items {
                near(27.5 * scale, height(*item), "a menu item");
            }
            assert_eq!(placed.items.len(), THEME_OPTIONS.len());
        }
    }

    /// PIN (modal): while the dialog is up every point in the window belongs to
    /// the overlay, and the points that are *not* the dialog belong to the
    /// scrim — including the caption run the gear itself lives in.
    ///
    /// Red gate: the gear's own box is computed here from the same numbers
    /// `seats::hit_window_chrome` uses, and that function is asserted to still
    /// call it the gear. If the point were not really the gear the claim below
    /// would be vacuous.
    #[test]
    fn the_scrim_swallows_the_caption_run_the_gear_lives_in() {
        let placed = open(1.0, false);
        let (surface_width, scale) = (SURFACE.0, 1.0_f32);
        let button = bt_render::WINDOW_CAPTION_BUTTON_LOGICAL_PX * scale;
        let gear = f64::from(surface_width - 4.0 * button + button / 2.0);
        let y = f64::from(bt_render::WINDOW_TITLE_BAR_LOGICAL_PX * scale / 2.0);
        assert_eq!(
            crate::seats::hit_window_chrome(
                surface_width,
                scale,
                crate::seats::RailState::default(),
                gear,
                y,
            ),
            Some(crate::seats::ChromeTarget::Settings),
            "the point under test really is the gear"
        );
        assert_eq!(
            hit(&placed, &values(), gear, y),
            SettingsTarget::Scrim,
            "a modal means MODAL: the gear is behind the scrim like everything else"
        );
    }

    /// PIN (modal): a sweep of the whole window never lands outside the overlay,
    /// and every point that is not the dialog or its menu is the scrim.
    #[test]
    fn no_point_in_the_window_escapes_the_overlay() {
        let placed = open(1.0, true);
        let menu = placed.menu.expect("the menu is open");
        let mut seen_scrim = false;
        let mut seen_panel = false;
        let mut y = 0.0_f32;
        while y < SURFACE.1 {
            let mut x = 0.0_f32;
            while x < SURFACE.0 {
                let target = hit(&placed, &values(), f64::from(x), f64::from(y));
                let inside_dialog = contains(placed.frame, x, y);
                let inside_menu = contains(menu, x, y);
                match target {
                    SettingsTarget::Scrim => {
                        assert!(
                            !inside_dialog && !inside_menu,
                            "({x}, {y}) is on the dialog and was called scrim"
                        );
                        seen_scrim = true;
                    }
                    _ => {
                        assert!(
                            inside_dialog || inside_menu,
                            "({x}, {y}) is behind the scrim and was called {target:?}"
                        );
                        seen_panel = true;
                    }
                }
                x += 7.0;
            }
            y += 7.0;
        }
        assert!(seen_scrim && seen_panel, "the sweep must reach both");
    }

    /// PIN (hit test): every control answers where it is drawn, and the dialog's
    /// own body answers "nowhere" rather than "close".
    #[test]
    fn every_control_answers_where_it_is_drawn() {
        let placed = open(1.0, true);
        let (x, y) = centre(placed.close);
        assert_eq!(hit(&placed, &values(), x, y), SettingsTarget::Close);
        // Every row's button, on a dialog with nothing open over them — with a
        // picker up the row it hangs over belongs to the picker, which is
        // `a_press_inside_an_open_picker_never_reaches_the_row_beneath_it`.
        //
        // Each row is asked on a dialog scrolled to show it: this page is taller
        // than the capped frame, and a row below the fold is not a control that
        // answers wrongly — it is a control that is not on screen, which is
        // `a_row_scrolled_out_of_the_content_box_takes_no_press`.
        let at_rest = open(1.0, false);
        for placed_row in &at_rest.rows {
            let shut = open_scrolled(1.0, false, scroll_to_row(&at_rest, placed_row.row));
            let combo = row_of(&shut, placed_row.row).combo;
            let (x, y) = centre(combo);
            assert_eq!(
                hit(&shut, &values(), x, y),
                placed_row.row.control_target(),
                "{:?}'s control must answer for its own row",
                placed_row.row
            );
        }
        for (index, item) in placed.items.iter().enumerate() {
            let (x, y) = centre(*item);
            assert_eq!(
                hit(&placed, &values(), x, y),
                SettingsTarget::Choice(SettingsRow::Theme, index),
                "item {index} must answer for its own option"
            );
        }
        // The menu's own padding: inside the popup, on none of its items.
        let menu = placed.menu.expect("the menu is open");
        assert_eq!(
            hit(
                &placed,
                &values(),
                f64::from(menu[0] + 1.0),
                f64::from(menu[1] + 1.0)
            ),
            SettingsTarget::Menu(SettingsRow::Theme)
        );
        // The header, left of the title, is the dialog and nothing more.
        assert_eq!(
            hit(
                &placed,
                &values(),
                f64::from(placed.frame[0] + 4.0),
                f64::from(placed.frame[1] + 4.0),
            ),
            SettingsTarget::Panel
        );
    }

    /// PIN: the mapping a press on a picker item makes to `set_theme` — the one
    /// thing between "the user clicked Light" and the process being light.
    ///
    /// Red gate: nothing else in the overlay asks for a theme, so a router that
    /// switched on, say, the combo button would fail the second half.
    #[test]
    fn only_a_picker_item_asks_for_a_theme_and_it_asks_for_its_own() {
        let placed = open(1.0, true);
        for (index, item) in placed.items.iter().enumerate() {
            let (x, y) = centre(*item);
            assert_eq!(
                theme_requested(hit(&placed, &values(), x, y)),
                Some(THEME_OPTIONS[index])
            );
        }
        assert_eq!(
            THEME_OPTIONS,
            [ThemeModeV1::Light, ThemeModeV1::Dark, ThemeModeV1::System,]
        );
        for target in [
            SettingsTarget::Scrim,
            SettingsTarget::Panel,
            SettingsTarget::Close,
            SettingsTarget::Combo(SettingsRow::Theme),
            SettingsTarget::Menu(SettingsRow::Theme),
        ] {
            assert_eq!(
                theme_requested(target),
                None,
                "{target:?} asks for no theme"
            );
        }
    }

    #[test]
    fn each_cursor_picker_item_maps_to_its_corresponding_set_value() {
        let placed = open_cursor(1.0);
        assert_eq!(placed.items.len(), CURSOR_OPTIONS.len());
        for (index, item) in placed.items.iter().enumerate() {
            let (x, y) = centre(*item);
            let target = hit(&placed, &values(), x, y);
            assert_eq!(target, SettingsTarget::Choice(SettingsRow::Cursor, index));
            assert_eq!(cursor_style_requested(target), Some(CURSOR_OPTIONS[index]));
        }
        for target in [
            SettingsTarget::Scrim,
            SettingsTarget::Panel,
            SettingsTarget::Close,
            SettingsTarget::Combo(SettingsRow::Theme),
            SettingsTarget::Menu(SettingsRow::Theme),
            SettingsTarget::Combo(SettingsRow::Cursor),
            SettingsTarget::Menu(SettingsRow::Cursor),
        ] {
            assert_eq!(cursor_style_requested(target), None);
        }
    }

    #[test]
    fn cursor_combo_reuses_theme_combo_geometry_and_menu_craft() {
        let placed = open_cursor(1.0);
        let theme = combo_of(&placed, SettingsRow::Theme);
        let cursor = combo_of(&placed, SettingsRow::Cursor);
        assert_eq!(width(cursor), width(theme));
        assert_eq!(height(cursor), height(theme));
        // Measured against the row immediately above it rather than against
        // Theme: the two scheme rows moved in between (§7.1.6c-4a), then the
        // window's ground took six more (§7.1.6c-4b), and then §7.1.6c-5's
        // ruling put the ground under a disclosure and the two font rows here
        // instead. What this pins is the stacking step, not which row happens to
        // be second.
        let above = combo_of(&placed, SettingsRow::FontSize);
        assert_eq!(
            cursor[1] - above[1],
            ROW_HEIGHT,
            "the rows stack exactly one row height apart"
        );
        let (x, y) = centre(cursor);
        assert_eq!(
            hit(&placed, &values(), x, y),
            SettingsTarget::Combo(SettingsRow::Cursor)
        );
        assert_eq!(placed.items.len(), 3);
        let labels = labels_of(&placed, None, &values());
        for label in ["Bar", "Block", "Underline"] {
            assert!(labels.iter().any(|candidate| candidate.text == label));
        }
    }

    /// PIN: the picker's menu opens below its button, and flips above it when
    /// there is no room — measured against the window, which is what actually
    /// clips it (the mock-up's own rule, and its `.content` does not scroll).
    #[test]
    fn the_menu_opens_below_and_flips_up_when_it_would_spill() {
        let tall = open(1.0, true);
        let tall_combo = combo_of(&tall, SettingsRow::Theme);
        let menu = tall.menu.expect("the menu is open");
        assert_eq!(
            menu[1] - tall_combo[3],
            MENU_OFFSET_LOGICAL_PX,
            "top: calc(100% + 4px)"
        );
        assert_eq!(menu[2], tall_combo[2], "right: 0");
        assert_eq!(
            width(menu),
            width(tall_combo),
            "min-width: 100% — with one short word per option the floor is the width"
        );

        // A window whose bottom is right under the combo leaves no room below.
        //
        // 260 and not 200 since §7.1.6c-5: the scrollport is the content box
        // now, so ten pixels at the top and eighteen at the bottom are inset
        // rather than scrollable, and at 200 the Theme row no longer lands
        // wholly inside it — which makes its picker not open at all, and this
        // pin is about which way an open picker goes.
        let rows = flat_rows();
        let short = layout_for_menu(
            1280.0,
            260.0,
            1.0,
            Some(SettingsRow::Theme),
            None,
            content(&rows, &[]),
            PAGE,
            UNSCROLLED,
            MENU_UNSCROLLED,
            &mut flat(0.0),
        )
        .expect("260 tall still hosts the dialog");
        let short_combo = combo_of(&short, SettingsRow::Theme);
        let menu = short.menu.expect("the menu is open");
        assert_eq!(
            short_combo[1] - menu[3],
            MENU_OFFSET_LOGICAL_PX,
            "flipped up, the same 4px gap sits above the button"
        );
        assert!(
            menu[1] >= 0.0,
            "the flipped menu still starts inside the window"
        );
        // Items keep their order under the flip: the first option is still the
        // top one, so "the second item is Dark" does not depend on the flip.
        assert_eq!(short.items.len(), THEME_OPTIONS.len());
        assert!(short.items[0][1] < short.items[1][1]);
    }

    /// A settings list of `count` rows, cycling the real ones.
    ///
    /// Real rows and not invented ones: a row carries its own category, and it
    /// is the category changes that put a heading into the stack, so a synthetic
    /// row would be measuring an easier shape than the dialog actually holds.
    /// Twenty of these is the row count this module's growth is pinned against.
    ///
    /// **All from one page**, since a page is what a layout lays out: cycling
    /// rows across two categories would also break the contiguity the heading
    /// derivation depends on, which is a different bug wearing this test's
    /// clothes.
    fn many_rows(count: usize) -> Vec<SettingsRow> {
        let cycle: Vec<SettingsRow> = visible_rows(TabLayoutMode::Vertical)
            .into_iter()
            .filter(|row| row.category() == PAGE)
            .collect();
        (0..count).map(|index| cycle[index % cycle.len()]).collect()
    }

    /// The dialog holding `rows`, scrolled this far, in a normal window.
    fn scrolled(rows: &[SettingsRow], scroll: f32) -> SettingsLayout {
        scrolled_with(rows, every_group_open(), scroll)
    }

    /// The same, with the Advanced groups in a named state — what a claim about
    /// an *everyday* page has to say now that the dialog is capped at 600 and an
    /// open group is one of the two things that overflows it.
    fn scrolled_with(rows: &[SettingsRow], advanced: AdvancedOpen, scroll: f32) -> SettingsLayout {
        layout_for_menu(
            SURFACE.0,
            SURFACE.1,
            1.0,
            None,
            None,
            content_with(rows, &[], advanced),
            PAGE,
            scroll,
            MENU_UNSCROLLED,
            &mut flat(0.0),
        )
        .expect("this window hosts the dialog")
    }

    /// PIN (Bug 2): the dialog never grows out of the window it is in.
    ///
    /// `max-height: calc(100% - 72px)` is a cap, and a cap that content is
    /// allowed to overrun is not one. Before the content scrolled, the stack was
    /// laid out from the content box's top with no offset and simply ran past the
    /// bottom edge — at seven rows the Startup group's Default profile row was
    /// drawn below the frame and clipped away, which is exactly what the user saw.
    #[test]
    fn a_stack_taller_than_the_window_leaves_the_dialog_inside_it() {
        let rows = many_rows(20);
        let placed = scrolled(&rows, 0.0);
        assert_eq!(
            placed.frame[1],
            optical_top(SURFACE.1, height(placed.frame)),
            "the dialog keeps its share of the window's slack above it"
        );
        assert!(
            placed.frame[1] >= DIALOG_TOP_LOGICAL_PX,
            "and never comes nearer the caption than the mock-up's margin"
        );
        assert!(
            placed.frame[3] <= SURFACE.1 - DIALOG_BOTTOM_LOGICAL_PX,
            "20 rows must not push the frame past the window's bottom margin: \
             frame {:?} in a {}px window",
            placed.frame,
            SURFACE.1
        );
        assert!(
            placed.max_scroll() > 0.0,
            "a stack this tall overflows, so it must report somewhere to scroll"
        );
        // The overflow is exactly what the cap refused, so scrolling to the end
        // puts the last row's bottom on the content box's bottom.
        let end = scrolled(&rows, placed.max_scroll());
        let last = end.rows.last().expect("20 rows were placed");
        assert!(
            last.combo[3] <= end.content[3] + f32::EPSILON,
            "scrolled to the end, the last row is inside the content box: \
             combo {:?} content {:?}",
            last.combo,
            end.content
        );
    }

    /// PIN (Bug 2): every row can be brought into reach and pressed.
    ///
    /// The half of "it scrolls" that a height assertion cannot see. A row drawn
    /// inside the content box but still answering `Panel` to a press would be a
    /// dialog that shows a control it will not accept — so the claim is stated
    /// through `hit`, at the row's own combo, and not through the geometry the
    /// draw call happens to read.
    #[test]
    fn every_row_scrolls_into_reach_and_answers_a_press() {
        let rows = many_rows(20);
        let reference = scrolled(&rows, 0.0);
        let max = reference.max_scroll();
        assert_eq!(reference.rows.len(), rows.len());
        // Walked in the order the page **draws** them, which is not the order
        // they were handed over: since §7.1.6c-5 a page stacks its everyday rows
        // above its advanced ones, so an index into the input list names a
        // different row from the same index into the stack.
        for index in 0..reference.rows.len() {
            // Where this row sits when nothing is scrolled, turned into the
            // offset that puts it at the top of the content box — clamped, which
            // is what makes the first and last rows work without a special case.
            let unscrolled = reference.rows[index].combo;
            // Against the scrollport and not the padding box (§7.1.6c-5): the
            // ten pixels of top padding are the band a row disappears under, so
            // an offset measured from the padding box would leave every row ten
            // pixels short of being wholly inside.
            let want = (unscrolled[1] - reference.clip[1]).clamp(0.0, max);
            let placed = scrolled(&rows, want);
            let entry = placed.rows[index];
            let combo = entry.combo;
            assert!(
                placed.shows(combo),
                "row {index} ({:?}) never comes fully inside the scrollport: \
                 combo {combo:?} clip {:?} scroll {want}",
                entry.row,
                placed.clip
            );
            let (x, y) = centre(combo);
            assert_eq!(
                hit(&placed, &values(), x, y),
                entry.row.control_target(),
                "row {index} ({:?}) is visible but does not answer a press",
                entry.row
            );
        }
    }

    /// PIN (Bug 2): a row that has been scrolled out of the box is not pressable.
    ///
    /// The other side of the same rule, and the reason `hit` asks `shows` rather
    /// than testing the combo alone: the boxes still exist off the end of the
    /// content box, and a press landing on one of them would be the dialog acting
    /// on a control that is not on screen.
    #[test]
    fn a_row_scrolled_out_of_the_content_box_takes_no_press() {
        let rows = many_rows(20);
        let placed = scrolled(&rows, 0.0);
        let last = placed.rows.last().expect("20 rows were placed");
        assert!(
            last.combo[3] > placed.content[3],
            "this fixture depends on the last row overflowing"
        );
        let (x, y) = centre(last.combo);
        assert_eq!(
            hit(&placed, &values(), x, y),
            SettingsTarget::Scrim,
            "a combo below the dialog's own bottom edge is scrim, not a control"
        );
    }

    /// PIN (Bug 2): a list that fits does not scroll, and cannot be made to.
    ///
    /// The dialog as it stands today, so the wheel is a no-op until the row list
    /// actually outgrows the window — and the clamp is what makes the runtime's
    /// unclamped field safe to keep across a resize.
    ///
    /// **Stated with the Advanced group folded** since the dialog took its 600px
    /// cap: the page that fits is the everyday one, and an open group is one of
    /// the two things the cap deliberately leaves to scroll.
    #[test]
    fn a_stack_that_fits_reports_nowhere_to_scroll() {
        // **A page that genuinely fits**, which the Appearance page stopped being
        // in either layout. It read the horizontal Appearance page until
        // 2026-08-21: §7.1.6b′ had already pushed the vertical one 32px past 600
        // with focus mode's row, and the card-height row added that day carried
        // the horizontal one over too, so the fits example moved to a short page.
        // Rendered blocks holds four everyday rows and sits well under the cap.
        let fits = shaped(
            SettingsCategory::RenderedBlocks,
            AdvancedOpen::default(),
            None,
        );
        assert_eq!(
            fits.max_scroll(),
            0.0,
            "a four-row everyday page fits a {}px dialog with room to spare",
            DIALOG_MAX_HEIGHT_LOGICAL_PX
        );
        // **And the one that no longer fits says so by exactly its overflow.**
        // `DIALOG_MAX_HEIGHT_LOGICAL_PX`'s own doc rules this case — *"a page
        // that one day grows past 600 must scroll rather than swallow the
        // window"* — so the honest statement is not that everyday pages never
        // scroll, it is that the dialog stays a dialog and the surplus goes
        // under the fold.
        let railed = visible_rows(TabLayoutMode::Vertical);
        let overflowing = scrolled_with(&railed, AdvancedOpen::default(), 0.0);
        // **This page's own height, not the cap.** The two were the same number
        // for as long as `Appearance` was the tallest everyday page, and §7.54b
        // ⑤ ended that: `General` is taller now, so a claim written against
        // `everyday_cap_height` would be measuring one page's scroll against
        // another page's height. What the ceiling rules is that the *dialog*
        // stops growing; what each page owes is that its own surplus goes under
        // the fold, and this is that page's surplus.
        assert_eq!(
            overflowing.max_scroll().round(),
            (folded_page_height(PAGE) - DIALOG_MAX_HEIGHT_LOGICAL_PX)
                .max(0.0)
                .round(),
            "the page on the glass scrolls by exactly what it stands over the ceiling"
        );
        let shoved = shaped_scrolled(
            SettingsCategory::RenderedBlocks,
            AdvancedOpen::default(),
            None,
            4_000.0,
        );
        assert_eq!(
            shoved.rows[0].combo, fits.rows[0].combo,
            "an offset a list this short cannot honour is clamped away, not applied"
        );
    }

    /// PIN (Bug 2): the picker lets go of a row that scrolls out from under it.
    ///
    /// A popup is anchored to its button. The same sentence the Sidebar row
    /// already answers when the Tab layout combo takes it out of the list, asked
    /// of the other way a row can leave: the content moving under it.
    #[test]
    fn a_picker_whose_row_scrolls_away_is_not_open() {
        let rows = many_rows(20);
        let anchored = layout_for_menu(
            SURFACE.0,
            SURFACE.1,
            1.0,
            Some(SettingsRow::Theme),
            None,
            content(&rows, &[]),
            PAGE,
            UNSCROLLED,
            MENU_UNSCROLLED,
            &mut flat(0.0),
        )
        .expect("this window hosts the dialog");
        assert!(
            anchored.menu.is_some(),
            "the Theme row is on screen unscrolled, so its picker hangs from it"
        );
        let past = layout_for_menu(
            SURFACE.0,
            SURFACE.1,
            1.0,
            Some(SettingsRow::Theme),
            None,
            content(&rows, &[]),
            PAGE,
            anchored.max_scroll(),
            MENU_UNSCROLLED,
            &mut flat(0.0),
        )
        .expect("this window hosts the dialog");
        assert!(
            past.menu.is_none(),
            "scrolled to the end, the Theme row is gone and its picker has \
             nothing to hang from"
        );
    }

    /// The value a row's button shows for [`values`], which is the string the
    /// button has to fit — `None` for a row that has no button.
    ///
    /// A slider has no ticked item and no ellipsis to get wrong: its caption is
    /// three characters of tabular digits in a column measured for four, so the
    /// two pins that read a drawn value skip it rather than inventing a claim
    /// about a control that cannot overflow.
    fn shown_value(row: SettingsRow) -> Option<&'static str> {
        if row.control().range().is_some() {
            return None;
        }
        Some(
            row.selected_index(&values())
                .and_then(|index| row.option_label(index))
                .expect("every picker row this dialog holds reads something"),
        )
    }

    /// The box a button's value is laid out in at 1x — the button less its two
    /// hairlines, its padding and the chevron's reserved column.
    ///
    /// [`push_combo`]'s own arithmetic, written once here so the two pins that
    /// read a drawn value find it the same way.
    fn combo_value_box(combo: [f32; 4]) -> [f32; 4] {
        [
            combo[0] + 1.0 + COMBO_PADDING_LEFT_LOGICAL_PX,
            combo[1],
            combo[2]
                - 1.0
                - COMBO_PADDING_RIGHT_LOGICAL_PX
                - COMBO_CHEVRON_FONT_LOGICAL_PX
                - COMBO_GAP_LOGICAL_PX,
            combo[3],
        ]
    }

    /// PIN (Bug 1 — the edge rows were compressed): a row that only partly
    /// reaches the content box is **cut**, never shortened.
    ///
    /// The report, on a scrolled dialog: the row at the top edge (Theme) and the
    /// one at the bottom (Default profile) came out *squat* — the combo a shorter
    /// pill with its corners rounded on the cut, the title jammed against the
    /// edge — rather than whole rows with their overflow hidden. "无论上边下边,
    /// 显示不全的框的高度都会被压缩."
    ///
    /// The cause was that every piece of the stack was built **from**
    /// `clipped(box, content)`: the crop was handed in as the geometry, so a
    /// `ChromeLabel` re-laid-out and re-centred its glyphs inside the sliver, and
    /// `rounded_overlay_fill` put a real corner wherever the cut happened to fall.
    /// Clamping a rectangle and clipping a drawing look alike from a distance and
    /// are not the same operation.
    ///
    /// Stated as the law [`clip_content`] installs: **geometry translates, only
    /// drawing is cut.** A label's layout box is the row's own box at every
    /// offset, wearing the crop as a `clip` beside it; the button's fills are the
    /// whole button's fills with whatever lies outside dropped.
    ///
    /// Red gate: hand the crop back to either channel — `rect: clipped(...)` on
    /// the labels, or `push_combo(..., clipped(placed.combo, clip), ...)` on the
    /// fills — and the matching half of this fails on the first cut row.
    #[test]
    fn a_row_at_the_content_edge_is_cut_and_never_compressed() {
        let rows = many_rows(20);
        let reference = scrolled(&rows, 0.0);
        let max = reference.max_scroll();
        assert!(max > 0.0, "this fixture depends on a stack that overflows");
        let palette = chrome_palette();
        let border = FLOAT_WINDOW_BORDER_LOGICAL_PX.max(1.0);
        let mut rows_cut = 0;
        for step in 0..=8 {
            let placed = scrolled(&rows, max * step as f32 / 8.0);
            // The scrollport, which is where the cut actually falls
            // (§7.1.6c-5) — the padding box would predict a crop ten pixels
            // taller at the top and eighteen at the bottom than the one drawn.
            let content = placed.clip;
            let labels = labels_of(&placed, None, &values());
            let quads = quads_of(&placed, None, &values());
            for row in &placed.rows {
                // Text: the row's own boxes are the layout boxes, whatever the
                // crop, and a box with nothing showing draws nothing at all.
                for (box_of, text) in [
                    (row.title, row.row.title()),
                    (row.desc, row.row.description(&values())),
                ] {
                    match clipped(box_of, content) {
                        None => assert!(
                            !labels.iter().any(|label| label.rect == box_of),
                            "{:?}: a box wholly outside the content draws nothing",
                            row.row
                        ),
                        Some(window) => {
                            let drawn = labels
                                .iter()
                                .find(|label| label.rect == box_of)
                                .unwrap_or_else(|| {
                                    panic!(
                                        "{:?}: {text:?} is laid out in the box the row was given, \
                                         {box_of:?} — not in the crop. Labels: {:?}",
                                        row.row,
                                        labels.iter().map(|label| label.rect).collect::<Vec<_>>()
                                    )
                                });
                            assert_eq!(
                                drawn.clip,
                                Some(window),
                                "{:?}: {text:?} wears the crop as its clip",
                                row.row
                            );
                        }
                    }
                }
                // Fills: the whole button's fills, with the outside dropped. Built
                // here from the row's *full* combo so the comparison is against
                // the shape the button is, not against the shape the cut left.
                // A slider is not a button and has no fills to compare against
                // a button's; the clipping it owes is the same clipping every
                // other quad in the content stack owes, which the sweep below
                // already covers.
                let Some(button_value) = shown_value(row.row) else {
                    if clipped(row.combo, content).is_some_and(|seen| seen != row.combo) {
                        rows_cut += 1;
                    }
                    continue;
                };
                let mut whole_quads = Vec::new();
                let mut whole_labels = Vec::new();
                push_combo(
                    &mut whole_quads,
                    &mut whole_labels,
                    row.combo,
                    false,
                    button_value,
                    true,
                    1.0,
                    border,
                    palette,
                    &mut measure,
                );
                if clipped(row.combo, content).is_some_and(|seen| seen != row.combo) {
                    rows_cut += 1;
                }
                for whole in whole_quads {
                    let Some(rect) = clipped(whole.rect, content) else {
                        continue;
                    };
                    let cut = OverlayQuad { rect, ..whole };
                    assert!(
                        quads.contains(&cut),
                        "{:?}: the button's fill {:?} reaches the screen as {cut:?} — a run cut \
                         by the content edge, not a shorter button's own run",
                        row.row,
                        whole.rect
                    );
                }
            }
        }
        assert!(
            rows_cut > 0,
            "no offset in this sweep actually cut a row, so the pin proved nothing"
        );
    }

    /// PIN (Bug 1): scrolling **moves** the stack and does nothing else.
    ///
    /// The geometry half of the law, and the stronger statement of the two: not
    /// merely that a row keeps its height at every offset, but that the whole
    /// stack at offset *s* is the stack at rest slid up by exactly *s* — every
    /// heading, every title, every description, every button. A layout that
    /// clamped a rectangle into the content box would fail this before any
    /// drawing was asked for, which is the point of stating it here as well as at
    /// the draw: the two are different places the same mistake can be made, and
    /// [`clip_content`] can only be honest about a stack that was honest first.
    #[test]
    fn scrolling_translates_the_stack_and_changes_nothing_else() {
        let rows = many_rows(20);
        let rest = scrolled(&rows, 0.0);
        let max = rest.max_scroll();
        assert!(max > 0.0, "this fixture depends on a stack that overflows");
        let slid = |rect: [f32; 4], by: f32| [rect[0], rect[1] - by, rect[2], rect[3] - by];
        for step in 0..=16 {
            let by = max * step as f32 / 16.0;
            let placed = scrolled(&rows, by);
            assert_eq!(
                placed.content, rest.content,
                "the box the stack slides behind does not move with it"
            );
            for (moved, still) in placed.groups.iter().zip(&rest.groups) {
                assert_eq!(
                    moved.label,
                    slid(still.label, by),
                    "{:?}'s heading at offset {by}",
                    moved.group
                );
            }
            for (moved, still) in placed.rows.iter().zip(&rest.rows) {
                assert_eq!(
                    [moved.title, moved.desc, moved.combo],
                    [
                        slid(still.title, by),
                        slid(still.desc, by),
                        slid(still.combo, by)
                    ],
                    "{:?} at offset {by} is its resting self, moved",
                    moved.row
                );
            }
        }
    }

    /// PIN (Bug 1, second half): a value too wide for its button ends in a `…`.
    ///
    /// `.combo > button` is a fixed 118px and the value inside it is whatever the
    /// chosen option is called, so the two collide the moment an option has a long
    /// name — which "Windows PowerShell 5.1" is, and which is how the user met
    /// this: the Default profile button read `Windows Pov`, a name cut mid-glyph
    /// by the label's own box. A crop mid-glyph reads as a rendering fault; an
    /// ellipsis reads as a name too long, which is what it is.
    ///
    /// Two claims, and the second is the one that makes the first mean anything:
    /// every button's value fits its box, **and** a value that had to give way is
    /// a prefix of its own option marked with the `…`, never some other string.
    ///
    /// Red gate: drop the [`ellipsized`] call and the Default profile row fails
    /// the width claim with the whole title in a box that cannot hold it.
    #[test]
    fn a_value_too_wide_for_its_button_is_ellipsised_not_cropped() {
        let mut ellipsised = Vec::new();
        let mut placed_rows = Vec::new();
        for category in SettingsCategory::ALL {
            let at_rest = open_page(1.0, None, TabLayoutMode::Vertical, category, 0.0);
            for entry in &at_rest.rows {
                // One dialog per row, scrolled to show it: since the height took
                // its 600px cap a page can be taller than the frame, and a value
                // below the fold is not drawn at all — which is a different
                // claim from the one this pin makes.
                let page = open_page_scrolled(
                    1.0,
                    None,
                    TabLayoutMode::Vertical,
                    category,
                    0.0,
                    scroll_to_row(&at_rest, entry.row),
                );
                let row = row_of(&page, entry.row);
                placed_rows.push((page, row));
            }
        }
        for (placed, row) in &placed_rows {
            let labels = labels_of(placed, None, &values());
            // Sliders have no value box and nothing that can outgrow one.
            let Some(whole) = shown_value(row.row) else {
                continue;
            };
            let box_of = combo_value_box(row.combo);
            let drawn = labels
                .iter()
                .find(|label| label.rect == box_of)
                .unwrap_or_else(|| panic!("{:?}'s button draws its value", row.row));
            assert!(
                measure(&drawn.text, COMBO_FONT_LOGICAL_PX) <= width(box_of),
                "{:?}: {:?} is drawn in a box only {} wide",
                row.row,
                drawn.text,
                width(box_of)
            );
            if drawn.text == whole {
                continue;
            }
            let drawn = drawn.clone();
            let kept = drawn
                .text
                .strip_suffix(ELLIPSIS)
                .unwrap_or_else(|| panic!("{:?}: {:?} gave way without a …", row.row, drawn.text));
            assert!(
                whole.starts_with(kept) && !kept.is_empty(),
                "{:?}: {kept:?} is a prefix of {whole:?} and not a different word",
                row.row
            );
            ellipsised.push(row.row);
        }
        // **The family picker is excluded from the exact list, and only from
        // it.** Its values are the names of whatever fonts the machine running
        // this test has installed — `Cascadia Mono` fits and
        // `DejaVu Sans Mono for Powerline` does not — so asserting whether it
        // ellipsises would be asserting a fact about a font list this repository
        // does not own. Every mechanical claim above still applies to it: the
        // drawn text fits the box, and if it gave way it gave way with an `…`
        // after a prefix of the real name.
        ellipsised.retain(|row| *row != SettingsRow::TerminalFont);
        ellipsised.sort_by_key(|row| format!("{row:?}"));
        assert_eq!(
            ellipsised,
            vec![SettingsRow::DefaultProfile, SettingsRow::SplitDirection],
            "the long profile title and `Auto (longer edge)` are the two \
             values this build's own tables can produce that cannot fit the \
             118px button, and every other row's option is one short word that \
             must be left alone"
        );
    }

    /// PIN: [`ellipsized`] keeps the **longest** prefix that fits, and cuts only
    /// between characters.
    ///
    /// The rule the drawn pin above rests on, stated where it can be stated
    /// exactly. The "longest" half is what separates a real `text-overflow` from a
    /// truncation that throws away room it was given; the boundary half is what
    /// keeps a multi-byte name from being cut into invalid UTF-8, which a byte
    /// index would do and which no amount of measuring would catch.
    #[test]
    fn the_ellipsis_keeps_the_longest_prefix_that_fits() {
        let font = 10.0;
        let advance = font * TEST_ADVANCE_PER_EM;
        let text = "Windows PowerShell 5.1";
        assert_eq!(
            ellipsized(text, advance * 100.0, font, &mut measure),
            text,
            "a value with room to spare is left alone, ellipsis and all"
        );
        for characters in 1..text.chars().count() {
            let room = advance * characters as f32;
            let cut = ellipsized(text, room, font, &mut measure);
            assert!(
                measure(&cut, font) <= room,
                "{cut:?} does not fit {characters} characters' worth"
            );
            let kept = cut.strip_suffix(ELLIPSIS).expect("a cut value is marked");
            assert!(text.starts_with(kept), "{kept:?} is a prefix of {text:?}");
            // The longest such prefix: one more character would overflow. The `…`
            // itself takes one character's room in this measure, so the prefix is
            // one shorter than the room allows.
            assert_eq!(
                kept.chars().count(),
                characters.saturating_sub(1),
                "{cut:?} left room unused in {characters} characters' worth"
            );
        }
        // Nothing fits, and a `…` is still what CSS draws — the box does the rest.
        assert_eq!(ellipsized(text, 0.0, font, &mut measure), ELLIPSIS);
        // Cut between characters, never inside one: every prefix of a name whose
        // characters are three bytes each is still a name.
        let wide = "文件资源管理器";
        for characters in 1..=wide.chars().count() {
            let cut = ellipsized(wide, advance * characters as f32, font, &mut measure);
            let kept = cut.strip_suffix(ELLIPSIS).unwrap_or(&cut);
            assert!(
                wide.starts_with(kept),
                "{kept:?} is a whole-character prefix of {wide:?}"
            );
        }
    }

    /// PIN (B23) — the *left* cut keeps the longest **suffix** that fits, which
    /// on a path is the part that answers "where am I".
    ///
    /// The mirror of the test above, and the rule both feet are drawn by: a
    /// float's `.fly-foot` and a docked column's `.files-foot` both show a full
    /// path in a strip narrower than one, and a right cut would give
    /// `C:\Users\Alice\Developer\foli…` — every character of which the user
    /// already knew. The user's own screenshot of what they wanted is the second
    /// assertion here: `…ers\Alice\Developer\folio-terminal`.
    #[test]
    fn the_left_ellipsis_keeps_the_longest_suffix_that_fits() {
        let font = 10.0;
        let advance = font * TEST_ADVANCE_PER_EM;
        let text = r"C:\Users\Alice\Developer\folio-terminal";
        assert_eq!(
            ellipsized_left(text, advance * 100.0, font, &mut measure),
            text,
            "a path with room to spare is left whole"
        );
        // The width the user photographed: room for a `…` and the last 34
        // characters, which is exactly where their own screenshot cut.
        assert_eq!(
            ellipsized_left(text, advance * 35.0, font, &mut measure),
            format!("{ELLIPSIS}ers\\Alice\\Developer\\folio-terminal"),
            "the folder you are in survives; the drive letter is what goes"
        );
        for characters in 1..text.chars().count() {
            let room = advance * characters as f32;
            let cut = ellipsized_left(text, room, font, &mut measure);
            assert!(
                measure(&cut, font) <= room,
                "{cut:?} does not fit {characters} characters' worth"
            );
            let kept = cut.strip_prefix(ELLIPSIS).expect("a cut path is marked");
            assert!(text.ends_with(kept), "{kept:?} is a suffix of {text:?}");
            // The longest such suffix, by the same arithmetic as the prefix
            // test: the `…` costs one character's room.
            assert_eq!(
                kept.chars().count(),
                characters.saturating_sub(1),
                "{cut:?} left room unused in {characters} characters' worth"
            );
        }
        assert_eq!(ellipsized_left(text, 0.0, font, &mut measure), ELLIPSIS);
        // And cut between characters: a path with three-byte names in it is
        // still a path after the cut.
        let wide = r"C:\用户\伟毅\开发\终端";
        for characters in 1..=wide.chars().count() {
            let cut = ellipsized_left(wide, advance * characters as f32, font, &mut measure);
            let kept = cut.strip_prefix(ELLIPSIS).unwrap_or(&cut);
            assert!(
                wide.ends_with(kept),
                "{kept:?} is a whole-character suffix of {wide:?}"
            );
        }
    }

    /// PIN: a window that cannot host the dialog answers `None` rather than a
    /// squashed one — and the runtime reads `None` as "shut", so nothing is
    /// trapped behind a modal with nothing on it.
    #[test]
    fn a_window_too_small_to_host_the_dialog_says_so() {
        let rows = flat_rows();
        let sized = |width: f32, height: f32| {
            layout_for_menu(
                width,
                height,
                1.0,
                None,
                None,
                content(&rows, &[]),
                PAGE,
                UNSCROLLED,
                MENU_UNSCROLLED,
                &mut flat(0.0),
            )
        };
        assert!(sized(1280.0, 100.0).is_none(), "too short");
        // **The floor moved with the rail** (2026-08-17). It used to be the
        // 118px picker alone; it is now the rail, the two gutters and that
        // picker, because a page with no room for the control every row of it
        // ends in is not a narrower version of this design.
        let floor =
            NAV_WIDTH_LOGICAL_PX + 2.0 * CONTENT_PADDING_X_LOGICAL_PX + COMBO_MIN_WIDTH_LOGICAL_PX;
        assert!(sized(100.0, 800.0).is_none(), "too narrow");
        assert!(
            sized(floor / DIALOG_WIDTH_RATIO - 4.0, 800.0).is_none(),
            "one pixel under the floor is still under it"
        );
        assert!(
            sized(floor / DIALOG_WIDTH_RATIO + 4.0, 800.0).is_some(),
            "and just over it the dialog opens"
        );
        assert!(sized(1280.0, 800.0).is_some(), "a real window");
    }

    /// PIN (Esc): one layer per press — the open menu first, then the dialog,
    /// then nothing, and "nothing" is reported so the key can fall through to
    /// whoever owns it next.
    #[test]
    fn escape_unwinds_one_layer_per_press() {
        let mut panel = SettingsPanel::default();
        let rows = flat_rows();
        let lines = shortcut_lines();
        assert!(!panel.close_one_layer(), "nothing is open yet");
        panel.toggle(content(&rows, &lines));
        panel.toggle_menu(SettingsRow::Theme);
        assert!(panel.close_one_layer());
        assert!(
            panel.is_open() && panel.menu().is_none(),
            "the menu went first"
        );
        assert!(panel.close_one_layer());
        assert!(!panel.is_open(), "the dialog went second");
        assert!(!panel.close_one_layer(), "and then there is nothing left");
    }

    /// PIN: the gear toggles, and shutting the dialog takes the menu with it —
    /// so reopening never shows a picker the user never opened.
    #[test]
    fn the_gear_toggles_and_shutting_takes_the_menu_with_it() {
        let mut panel = SettingsPanel::default();
        let rows = flat_rows();
        let lines = shortcut_lines();
        panel.toggle(content(&rows, &lines));
        assert!(panel.is_open());
        panel.toggle_menu(SettingsRow::Theme);
        panel.toggle(content(&rows, &lines));
        assert!(!panel.is_open() && panel.menu().is_none());
        panel.toggle(content(&rows, &lines));
        assert!(panel.is_open() && panel.menu().is_none());
        panel.close();
        assert!(!panel.is_open());
    }

    /// How wide a chrome label is, for tests — one flat advance per character.
    ///
    /// A stand-in for the renderer's shaper on purpose. Every claim below that
    /// touches text width is a claim about the *rule* — "the whole string, or a
    /// prefix and a `…`, and never more than the box" — and a rule stated against
    /// a real face would be re-stating Segoe UI's metrics, which no assertion
    /// should own and which change with the font the machine has.
    const TEST_ADVANCE_PER_EM: f32 = 0.5;

    fn measure(text: &str, font_size_px: f32) -> f32 {
        text.chars().count() as f32 * font_size_px * TEST_ADVANCE_PER_EM
    }

    /// The overlay as it is drawn, measured by [`measure`].
    fn built(
        placed: &SettingsLayout,
        hover: Option<SettingsTarget>,
        values: &SettingsValues,
    ) -> Vec<OverlayLayer> {
        built_with(placed, hover, None, values, None)
    }

    /// The same, with a ring and a capture the caller names.
    fn built_with(
        placed: &SettingsLayout,
        hover: Option<SettingsTarget>,
        focus: Option<SettingsTarget>,
        values: &SettingsValues,
        recording: Option<(usize, &[String], Option<&str>)>,
    ) -> Vec<OverlayLayer> {
        let lines = shortcut_lines();
        build(
            placed,
            hover,
            focus,
            values,
            &lines,
            &[],
            "",
            recording,
            None,
            &mut measure,
        )
    }

    /// Every fill the overlay draws, whatever layer it is on — the question
    /// "does the dialog paint this at all" is not a question about z-order.
    fn quads_of(
        placed: &SettingsLayout,
        hover: Option<SettingsTarget>,
        values: &SettingsValues,
    ) -> Vec<OverlayQuad> {
        built(placed, hover, values)
            .into_iter()
            .flat_map(|layer| layer.quads)
            .collect()
    }

    fn labels_of(
        placed: &SettingsLayout,
        hover: Option<SettingsTarget>,
        values: &SettingsValues,
    ) -> Vec<ChromeLabel> {
        built(placed, hover, values)
            .into_iter()
            .flat_map(|layer| layer.labels)
            .collect()
    }

    /// Everything drawn on the page, put back into one string in drawing order.
    ///
    /// **A row's sentence is not a label** — it is as many labels as it needed
    /// lines, and how many that is depends on the fonts this machine has and on
    /// how long the sentence happens to be today. A test that wants to know
    /// whether the sentence is *drawn* therefore asks this and not
    /// `any(|label| label.text == sentence)`, which was quietly asking the
    /// second question "did the copy fit on one line" — and which is why every
    /// row test in this file went red the day the copy was rewritten
    /// (2026-08-26) rather than the day a row stopped drawing its sentence.
    ///
    /// The lines are joined the way [`wrapped_description`] split them, so the
    /// sentence comes back word for word — see the wrap test, which asserts
    /// exactly that.
    fn drawn_text(labels: &[ChromeLabel]) -> String {
        labels
            .iter()
            .map(|label| label.text.as_str())
            .collect::<Vec<_>>()
            .join(" ")
    }

    fn sprites_of(
        placed: &SettingsLayout,
        hover: Option<SettingsTarget>,
        values: &SettingsValues,
    ) -> Vec<ChromeSprite> {
        built(placed, hover, values)
            .into_iter()
            .flat_map(|layer| layer.sprites)
            .collect()
    }

    /// Whether `inner` lies wholly inside `outer`.
    fn within(inner: [f32; 4], outer: [f32; 4]) -> bool {
        inner[0] >= outer[0] && inner[1] >= outer[1] && inner[2] <= outer[2] && inner[3] <= outer[3]
    }

    /// Whether the two rectangles share any area at all.
    fn overlaps(a: [f32; 4], b: [f32; 4]) -> bool {
        a[0] < b[2] && b[0] < a[2] && a[1] < b[3] && b[1] < a[3]
    }

    /// RED GATE — **the scrim is the first layer and it is alone on it.**
    ///
    /// `Runtime::refresh_overlay` splits this band in two at exactly that seam:
    /// the head of it dims and the tail of it dims *and travels four pixels*, on
    /// the arrival slice's rule that a dialog comes out of nowhere while the
    /// window behind it merely darkens. Put anything else on the scrim's layer
    /// and that thing stops travelling with the dialog it belongs to; put the
    /// scrim second and the whole dialog slides while the dimming stays put.
    ///
    /// Mutation: push the scrim back into `content`'s quads and the split takes
    /// the dialog's own face for a scrim.
    #[test]
    fn the_scrim_is_the_first_layer_and_carries_nothing_but_itself() {
        let placed = open(1.0, false);
        let layers = built(&placed, None, &values());
        let scrim = layers.first().expect("the dialog draws at least one layer");
        assert_eq!(
            scrim.quads.len(),
            1,
            "the scrim's layer holds one quad: the dimming"
        );
        assert_eq!(scrim.quads[0].color, chrome_palette().modal_scrim);
        assert_eq!(
            scrim.quads[0].rect,
            [0.0, 0.0, SURFACE.0, SURFACE.1],
            "and it is the whole window"
        );
        assert!(
            scrim.labels.is_empty() && scrim.sprites.is_empty(),
            "nothing else may ride on the layer that must not move"
        );
        assert!(
            layers.len() >= 2,
            "the dialog is on its own layer above the scrim"
        );
        assert!(
            layers[1..].iter().all(|layer| layer
                .quads
                .iter()
                .all(|quad| quad.rect != [0.0, 0.0, SURFACE.0, SURFACE.1])),
            "there is one scrim and it is not drawn twice"
        );
    }

    /// Which layer the open picker's own surface is drawn on.
    fn popup_layer(layers: &[OverlayLayer]) -> usize {
        let surface = chrome_palette().menu_surface;
        layers
            .iter()
            .position(|layer| layer.quads.iter().any(|quad| quad.color == surface))
            .expect("an open picker draws its own face in --menu")
    }

    /// PIN (z-order): an open picker is a layer of its own, it is the last one,
    /// and nothing but the picker is on it — so every product of every row lands
    /// underneath it, in whichever channel that row drew itself.
    ///
    /// This is the shape of the bug it exists to keep out, caught on screen with
    /// the Theme picker open: the popup hangs over the Cursor row, and the row's
    /// value, its chevron and its tick came back out through the popup's face.
    /// The reason is that the overlay draws a layer's fills, then its marks, then
    /// its text: the popup's surface is a *fill* and the row's value is *text*, so
    /// pushing the popup last covered the row's own fills and nothing else. Only
    /// a later layer covers a later channel.
    ///
    /// Stated as the geometry the screenshot shows: where the popup's rectangle
    /// crosses a row's, the row's drawing product is on a lower layer — never on
    /// the popup's, and never above it.
    ///
    /// Red gate: the second half is what fails while the popup shares the rows'
    /// layer, and it names the row content it found there. The last assertion
    /// keeps the whole test from going vacuous if the picker ever stops
    /// overhanging the row below it — there would then be nothing to cover.
    #[test]
    fn an_open_picker_is_the_last_layer_and_carries_nothing_but_itself() {
        let mut covered_row_products = 0;
        for kind in [
            SettingsRow::Theme,
            SettingsRow::Cursor,
            SettingsRow::TabLayout,
            SettingsRow::Sidebar,
        ] {
            let placed = open_rows(1.0, Some(kind), TabLayoutMode::Vertical);
            let menu = placed.menu.expect("the picker is open");
            let layers = built(&placed, None, &values());
            let popup = popup_layer(&layers);
            assert_eq!(
                popup,
                layers.len() - 1,
                "{kind:?}: nothing at all is drawn over an open picker"
            );

            // The popup's layer is the popup and only the popup. Its captions and
            // marks stand inside its own frame; its fills are that frame plus the
            // shadow it casts, which is the one thing it draws outside itself.
            let lift = FLOAT_WINDOW_SHADOW_LOGICAL_PX.ceil() + 1.0;
            let halo = [
                menu[0] - lift,
                menu[1] - lift,
                menu[2] + lift,
                menu[3] + lift,
            ];
            let top = &layers[popup];
            for label in &top.labels {
                assert!(
                    within(label.rect, menu),
                    "{kind:?}: {:?} at {:?} is not the picker's own text and shares its layer",
                    label.text,
                    label.rect
                );
            }
            for sprite in &top.sprites {
                assert!(
                    within(sprite.rect, menu),
                    "{kind:?}: {:?} is a mark on the picker's layer that is not the picker's",
                    sprite.mark
                );
            }
            for quad in &top.quads {
                assert!(
                    within(quad.rect, halo),
                    "{kind:?}: a fill at {:?} is on the picker's layer but outside its shadow",
                    quad.rect
                );
            }

            // Count what the popup is actually covering, for the vacuity guard
            // below: content that crosses the popup's rectangle and is drawn on
            // a layer under it.
            covered_row_products += layers[..popup]
                .iter()
                .flat_map(|layer| &layer.labels)
                .filter(|label| overlaps(label.rect, menu))
                .count();
        }
        // The claim is not vacuous: a picker really does hang over row content
        // that was on top of it before. The Theme picker is the one the
        // screenshot caught — it covers the row below's value and its chevron —
        // and every picker but the last row's does the same thing now.
        assert!(
            covered_row_products >= 2,
            "no picker overhangs any row's text, so this test proves nothing"
        );
    }

    /// PIN (modal, one layer down): a press inside an open picker belongs to the
    /// picker, even where the picker hangs over another row's control — the hit
    /// test reads the same z-order the draw does, so a click on the popup can
    /// never open a second one behind it.
    ///
    /// Red gate: the sweep is over the *intersection* of the popup and the combo
    /// it covers, and it is asserted to be a real rectangle first, so a hit test
    /// that answered the row under the popup would be caught by the sweep rather
    /// than by an empty loop.
    #[test]
    fn a_press_inside_an_open_picker_never_reaches_the_row_beneath_it() {
        let placed = open(1.0, true);
        let menu = placed.menu.expect("the picker is open");
        let covered = clipped(combo_of(&placed, SettingsRow::LightScheme), menu)
            .expect("the Theme picker hangs over the Light scheme row's control");
        let mut swept = 0;
        let mut y = covered[1] + 0.5;
        while y < covered[3] {
            let mut x = covered[0] + 0.5;
            while x < covered[2] {
                let target = hit(&placed, &values(), f64::from(x), f64::from(y));
                assert!(
                    matches!(
                        target,
                        SettingsTarget::Menu(SettingsRow::Theme)
                            | SettingsTarget::Choice(SettingsRow::Theme, _)
                    ),
                    "({x}, {y}) is under the open picker and answered {target:?}"
                );
                swept += 1;
                x += 3.0;
            }
            y += 3.0;
        }
        assert!(swept > 0, "the sweep must cover real ground");
    }

    /// Visual PIN: the scrim is the mock-up's own `rgba(15,15,15,.35)` across
    /// the whole window, and it is the *first* thing drawn, so everything else
    /// stands on it rather than under it.
    #[test]
    fn the_scrim_is_the_mock_ups_own_alpha_over_the_whole_window() {
        let placed = open(1.0, false);
        let palette = chrome_palette();
        let scrim = quads_of(&placed, None, &values())[0];
        assert_eq!(scrim.rect, [0.0, 0.0, SURFACE.0, SURFACE.1]);
        assert_eq!(scrim.color, [0x0f, 0x0f, 0x0f]);
        assert_eq!(scrim.color, palette.modal_scrim);
        assert!(
            (scrim.alpha - 0.35).abs() < 0.005,
            "the scrim is .35, saw {}",
            scrim.alpha
        );
    }

    /// Visual PIN (float-window craft): the dialog is a lift, a hairline and a
    /// face, and its corners carry partial coverage rather than a staircase —
    /// the same claim `rounded_rect.rs` pins for every window that floats.
    ///
    /// Red gate: nested rectangles put no pixel strictly between 0 and 1, so the
    /// partial-coverage count alone rules them out.
    #[test]
    fn the_dialog_wears_the_float_windows_craft_at_every_dpi() {
        for scale in [1.0_f32, 1.25, 1.5, 2.0] {
            let placed = open(scale, false);
            let palette = chrome_palette();
            let quads = quads_of(&placed, None, &values());
            let border_alpha = f32::from(palette.menu_border_alpha) / 255.0;
            let hairline = quads
                .iter()
                .filter(|quad| quad.color == palette.menu_border)
                .filter(|quad| (quad.alpha - border_alpha).abs() < 1e-4)
                .count();
            assert!(
                hairline > 0,
                "scale {scale}: the dialog wears --border at the mock-up's own alpha"
            );
            let face = quads
                .iter()
                .filter(|quad| quad.color == palette.dialog_surface && quad.alpha == 1.0)
                .count();
            assert!(face > 0, "scale {scale}: the dialog's face is --win");
            let lift = quads
                .iter()
                .filter(|quad| quad.color == palette.menu_shadow)
                .count();
            assert!(
                lift > 0,
                "scale {scale}: the dialog is lifted off the scrim"
            );
            let radius = FLOAT_WINDOW_RADIUS_LOGICAL_PX * scale;
            let partial = quads
                .iter()
                .filter(|quad| quad.alpha > 0.0 && quad.alpha < 1.0)
                .filter(|quad| quad.rect[2] - quad.rect[0] == 1.0)
                .filter(|quad| quad.color == palette.dialog_surface)
                .count();
            assert!(
                partial >= radius as usize,
                "scale {scale}: an antialiased quarter circle spends at least one \
                 partial pixel per row on the face, saw {partial}"
            );
        }
    }

    /// Visual PIN: the picker shows the selected mode, and marks it with the
    /// accent tick when the menu is open — exactly one tick, never two.
    #[test]
    fn the_picker_shows_and_ticks_the_selected_mode() {
        for selected in THEME_OPTIONS {
            let placed = open(1.0, true);
            let combo = combo_of(&placed, SettingsRow::Theme);
            let palette = chrome_palette();
            let labels = labels_of(
                &placed,
                None,
                &SettingsValues {
                    theme: selected,
                    ..values()
                },
            );
            let ticks: Vec<_> = labels.iter().filter(|label| label.text == TICK).collect();
            assert_eq!(ticks.len(), 1, "exactly one option is the selected mode");
            assert_eq!(ticks[0].color, palette.accent, "the tick is the accent");
            // The button says what the tick marks.
            let shown = theme_label(selected);
            let on_button = labels
                .iter()
                .find(|label| {
                    label.text == shown && label.rect[1] >= combo[1] && label.rect[3] <= combo[3]
                })
                .expect("the button shows the selected mode");
            assert_eq!(on_button.color, palette.dialog_title_text);
            // And the tick sits in the row of the option it marks.
            let index = THEME_OPTIONS
                .iter()
                .position(|option| *option == selected)
                .expect("the selected mode is one of the options");
            let item = placed.items[index];
            assert!(ticks[0].rect[1] >= item[1] && ticks[0].rect[3] <= item[3]);
        }
    }

    /// Visual PIN: hover paints one thing and only when something is hovered —
    /// the mock-up's `--hover` over the surface the control actually sits on.
    #[test]
    fn hover_paints_the_control_under_the_pointer_and_nothing_else() {
        let placed = open(1.0, true);
        let palette = chrome_palette();
        // **Everything the rail draws is excluded**, and deliberately: the
        // selected word wears `--hover` as its standing ground, which is a
        // *selection* and not a hover. Counting it here would make this test
        // read "one thing is lit when nothing is hovered", which is true and is
        // a different sentence from the one this pins.
        let nav = placed.nav;
        let count = |hover, color| {
            quads_of(&placed, hover, &values())
                .iter()
                .filter(|quad| quad.color == color)
                .filter(|quad| quad.rect[0] >= nav[2] || quad.rect[2] <= nav[0])
                .count()
        };
        assert_eq!(
            count(None, palette.dialog_hover),
            0,
            "nothing is lit when nothing is hovered"
        );
        assert!(
            count(Some(SettingsTarget::Close), palette.dialog_hover) > 0,
            "the close button takes --hover over --win"
        );
        assert!(
            count(
                Some(SettingsTarget::Combo(SettingsRow::Theme)),
                palette.dialog_hover
            ) > 0,
            "so does the combo button"
        );
        assert_eq!(
            count(
                Some(SettingsTarget::Menu(SettingsRow::Theme)),
                palette.menu_item_hover
            ),
            0,
            "the menu's own body is not an item"
        );
        assert!(
            count(
                Some(SettingsTarget::Choice(SettingsRow::Theme, 0)),
                palette.menu_item_hover
            ) > 0,
            "an item takes --hover over --menu, which is a different grey"
        );
    }

    /// The group heading is uppercase and tracked, which is the whole of what
    /// makes it read as a heading at 11px rather than as a small sentence.
    #[test]
    fn the_group_heading_is_uppercase_and_tracked() {
        let placed = open(1.0, false);
        let labels = labels_of(&placed, None, &values());
        let heading = labels
            .iter()
            .find(|label| label.text == "APPEARANCE")
            .expect("the Appearance group is headed");
        assert_eq!(heading.font_size_px, GROUP_LABEL_FONT_LOGICAL_PX);
        assert!(
            (heading.letter_spacing_em - 0.05).abs() < 1e-4,
            "letter-spacing: .05em, and em is a ratio"
        );
        assert_eq!(heading.color, chrome_palette().dialog_muted_text);
        // Red gate for a real bug this pass shipped and then caught on screen:
        // tracking was multiplied by the scaled font size on the way in, which
        // at 200% asked the shaper for 1.1 *em* per glyph and spelled the
        // heading out letter by letter. A ratio does not carry the DPI scale.
        for scale in [1.0_f32, 2.0] {
            let placed = open(scale, false);
            let labels = labels_of(&placed, None, &values());
            let heading = labels
                .iter()
                .find(|label| label.text == "APPEARANCE")
                .expect("the Appearance group is headed");
            assert!(
                (heading.letter_spacing_em - 0.05).abs() < 1e-4,
                "scale {scale}: tracking is the same ratio at every DPI, saw {}",
                heading.letter_spacing_em
            );
        }
    }

    /// Every page is headed by its own category's word, and every row on it is
    /// drawn under that heading.
    ///
    /// The heading is derived by walking the page's rows and noticing where the
    /// category changes, so on a page that holds one category it is exactly one
    /// heading — and a row drawn above it, or under a word that does not name
    /// it, is the derivation having come apart.
    #[test]
    fn every_page_is_headed_by_its_own_word_and_every_row_sits_under_it() {
        for category in SettingsCategory::ALL {
            if category == SettingsCategory::Shortcuts {
                continue;
            }
            let placed = open_page(1.0, None, TabLayoutMode::Vertical, category, 0.0);
            let labels = labels_of(&placed, None, &values());
            let headings: Vec<&ChromeLabel> = labels
                .iter()
                .filter(|label| label.text == category.label())
                .collect();
            if placed.rows.is_empty() {
                assert!(
                    headings.is_empty(),
                    "{category:?} has no rows and must draw no heading"
                );
                continue;
            }
            assert_eq!(headings.len(), 1, "{category:?} is headed exactly once");
            let heading = headings[0].rect[1];
            for placed_row in &placed.rows {
                assert!(
                    placed_row.title[1] > heading,
                    "{:?} is drawn above its own page's heading",
                    placed_row.row
                );
            }
            for other in SettingsCategory::ALL {
                if other == category {
                    continue;
                }
                assert!(
                    !labels.iter().any(|label| label.text == other.label()),
                    "{category:?}'s page draws {other:?}'s heading"
                );
            }
        }
    }

    /// Two rows of the Appearance page, named, so the sweep above cannot go
    /// green on a page that happens to hold nothing.
    #[test]
    fn the_appearance_page_holds_the_mock_ups_own_rows() {
        let placed = open_page(
            1.0,
            None,
            TabLayoutMode::Vertical,
            SettingsCategory::Appearance,
            0.0,
        );
        for row in [
            SettingsRow::Theme,
            SettingsRow::Cursor,
            SettingsRow::TabLayout,
            SettingsRow::Sidebar,
        ] {
            assert!(
                placed.row(row).is_some(),
                "{row:?} belongs to the Appearance page"
            );
        }
        assert!(
            placed.row(SettingsRow::Formulas).is_none(),
            "Display formulas belongs to Rendered blocks and is not on this page"
        );
    }

    /// PIN — **a page's heading takes the stylesheet's base `margin-top: 10px`,
    /// and there is no other margin left to take.**
    ///
    /// The mock-up used to say it twice: `.group-label { margin: 10px 0 2px }`
    /// for the first heading and an inline `margin-top:16px` on every later one,
    /// the extra six pixels separating one group from the next. With one
    /// category per page there is no next group on the page, the 16 was retired
    /// with the rail, and what this pins is the half that survived — plus the
    /// fact that it is now the *only* half, which is what stops the six pixels
    /// coming back as a rule nothing reads.
    #[test]
    fn a_pages_heading_takes_the_stylesheets_base_margin_and_stands_alone() {
        for scale in [1.0_f32, 1.5, 2.0] {
            let placed = open_page(
                scale,
                None,
                TabLayoutMode::Vertical,
                SettingsCategory::Appearance,
                0.0,
            );
            let labels = labels_of(&placed, None, &values());
            let heading = labels
                .iter()
                .find(|label| label.text == SettingsCategory::Appearance.label())
                .expect("the page is headed")
                .rect;

            let content_top = placed.content[1];
            assert!(
                (heading[1]
                    - (content_top
                        + (CONTENT_PADDING_TOP_LOGICAL_PX + GROUP_LABEL_MARGIN_TOP_LOGICAL_PX)
                            * scale))
                    .abs()
                    < 0.5,
                "scale {scale}: the heading keeps the stylesheet's 10px"
            );
            assert!(
                (heading[3] - heading[1] - GROUP_LABEL_LINE_LOGICAL_PX * scale).abs() < 0.5,
                "scale {scale}: every heading is one line box tall"
            );
            assert_eq!(
                placed.groups.len(),
                1,
                "scale {scale}: a page draws one heading, so there is no later one"
            );
        }
    }

    /// R4's lesson, asked again now that a second heading pushes the rows below it
    /// down: the height, the stack, the hit test and the draw are one derivation,
    /// so a row is never clickable somewhere it is not drawn.
    ///
    /// This is the red gate for the bug that shipped once already — geometry
    /// taught in one place and forgotten in another gives a control the user can
    /// press but cannot see.
    #[test]
    fn every_row_answers_the_pointer_where_its_own_page_put_it() {
        for tab_layout in [TabLayoutMode::Horizontal, TabLayoutMode::Vertical] {
            for scale in [1.0_f32, 1.25, 2.0] {
                for row in visible_rows(tab_layout) {
                    // On a dialog scrolled to show it: since the 600px cap a
                    // page can be taller than the frame, and the claim is that a
                    // row answers where it is *drawn* — not that every row of
                    // every page is drawn at once.
                    let at_rest = open_page(scale, None, tab_layout, row.category(), 0.0);
                    let placed = open_page_scrolled(
                        scale,
                        None,
                        tab_layout,
                        row.category(),
                        0.0,
                        scroll_to_row(&at_rest, row),
                    );
                    let combo = placed.row(row).expect("a visible row is placed").combo;
                    let centre = (
                        f64::from((combo[0] + combo[2]) / 2.0),
                        f64::from((combo[1] + combo[3]) / 2.0),
                    );
                    assert_eq!(
                        hit(&placed, &values(), centre.0, centre.1),
                        row.control_target(),
                        "{tab_layout:?} at {scale}: {row:?}'s control must answer \
                         where it is drawn"
                    );
                }
            }
        }
    }

    /// The dialog is as tall as everything an everyday page is holding — its
    /// heading included.
    ///
    /// A height that forgot the heading would push the last row past the bottom
    /// of the content box and clip it away, which is the bug that shipped once.
    ///
    /// **Everyday**, since the height took its 600px cap: the two things the cap
    /// deliberately leaves below the fold are the shortcut table and an
    /// `Advanced` group somebody opened, and both are named in
    /// [`the_capped_dialog_holds_every_everyday_page_and_only_the_long_ones_scroll`]
    /// rather than assumed away here.
    #[test]
    fn the_dialog_makes_room_for_every_heading_it_draws() {
        for category in SettingsCategory::ALL {
            if category == SettingsCategory::Shortcuts {
                continue;
            }
            let at_rest = shaped(category, AdvancedOpen::default(), None);
            // **Scrolled to the end of the page.** The claim is that the *page*
            // was measured with its heading in it, and a page that reaches the
            // reader by scrolling has reached them: since a sentence became a
            // height (2026-08-25) an everyday page can be taller than the frame's
            // own 600px ceiling, which is the case that ceiling's doc rules on —
            // it scrolls rather than swallowing the window. A height that forgot
            // the heading is still caught, and caught harder: the scroll range is
            // derived from the same number, so a page short by a heading leaves
            // its last row below the fold with nowhere left to scroll.
            let placed = shaped_scrolled(
                category,
                AdvancedOpen::default(),
                None,
                at_rest.max_scroll(),
            );
            let content = placed.content;
            let Some(last) = placed.rows.last() else {
                continue;
            };
            assert!(
                last.band[3] + CONTENT_PADDING_BOTTOM_LOGICAL_PX <= content[3] + 0.5,
                "{category:?}: the last row and the content's bottom padding both \
                 fit inside the content box once the page is scrolled to its end"
            );
        }
    }

    /// PIN (user report 2026-08-17, derivation 2026-08-18) — **the dialog stops
    /// at its tallest everyday page on a window that could host far more, and
    /// every everyday page fits inside it unscrolled.**
    ///
    /// The report: one height whatever page is up means the *tallest* page sets
    /// it, the tallest page is the forty-line shortcut table, and the dialog
    /// arrived running from the caption to the bottom edge on an ordinary window
    /// — a whole-window surface, which is the one shape the width's own cap was
    /// chosen to avoid.
    ///
    /// So the height takes a cap of its own, and the cap is measured rather than
    /// chosen: it is the tallest page with every `Advanced` group folded and
    /// neither of the two lists on it — the three things the ruling already left
    /// below the fold. 600 was that measurement written down as a literal on the
    /// day it was taken; [`everyday_cap`] is the measurement itself, so the day a
    /// page grows a row the cap grows with it instead of the page quietly
    /// growing a scroll bar.
    ///
    /// Red gate: drop the `.min(… everyday_cap …)` and the first assertion goes
    /// red at 947; fold the shortcut lines back into the sweep and it goes red
    /// the other way.
    #[test]
    fn the_capped_dialog_holds_every_everyday_page_and_only_the_long_ones_scroll() {
        // **`Appearance` is no longer in this list** (2026-08-21). `shaped`
        // builds the page with the tabs across the top, where `Appearance` held
        // eight everyday rows and fit; §7.1.6b′ made nine under the rail and that
        // day's card-height row made nine across the top too, so even the
        // horizontal page now overflows the cap and joins the two things below
        // the fold.
        //
        // **And `General` is no longer in it either** (2026-09-02, §7.54). The
        // summoned terminal's two rows are the eighth and ninth on that page, and
        // nine rows is what the cap stopped holding the day `Appearance` reached
        // it — the same arithmetic, on the second page to reach the same number.
        // It is a consequence and not a regression: the cap is
        // `DIALOG_MAX_HEIGHT_LOGICAL_PX`'s own sentence — *"a page that one day
        // grows past 600 must scroll rather than swallow the window"* — and this
        // is a page having that day. The frame is still 600 for every page,
        // including the ones that overflow it, and the sweep below still holds
        // every page that does fit to fitting whole.
        for category in [SettingsCategory::Terminal, SettingsCategory::RenderedBlocks] {
            let placed = shaped(category, AdvancedOpen::default(), None);
            assert_eq!(
                height(placed.frame),
                capped_dialog_height().round(),
                "{category:?}: a {}px window still gets a dialog and not a surface",
                SURFACE.1
            );
            assert_eq!(
                placed.max_scroll(),
                0.0,
                "{category:?}: an everyday page has nothing below the fold"
            );
            for row in &placed.rows {
                assert!(
                    placed.shows(row.band),
                    "{category:?}: {:?} is not wholly inside the content box \
                     unscrolled: {:?} in {:?}",
                    row.row,
                    row.band,
                    placed.clip
                );
            }
            if let Some(group) = placed.advanced() {
                assert!(!group.open, "{category:?}: this fixture folds the group");
                assert!(
                    placed.shows(group.band),
                    "{category:?}: and its folded Advanced heading is inside it too"
                );
            }
        }
        // And the things that scroll, which is exactly what the cap was chosen
        // to leave outside: the shortcut table, a group opened — and, since
        // 2026-08-21, the everyday `Appearance` page itself, which the
        // card-height row carried over the ceiling in both layouts.
        assert!(
            shaped(SettingsCategory::Appearance, AdvancedOpen::default(), None).max_scroll() > 0.0,
            "the everyday Appearance page now stands over the cap it derives"
        );
        assert!(
            shaped(SettingsCategory::Shortcuts, AdvancedOpen::default(), None).max_scroll() > 0.0,
            "the shortcut table is longer than any dialog this build opens"
        );
        assert!(
            shaped(SettingsCategory::Appearance, every_group_open(), None).max_scroll() > 0.0,
            "and so is an Advanced group somebody opened"
        );
        // And the mock-up carries the same rule, because it is the only visual
        // authority this dialog has: a cap written here and not there would be a
        // number with nothing behind it.
        assert!(
            MOCKUP.contains("max-height: min(600px, calc(100% - 72px));"),
            "`design/ui-mockup.html` says `.settings {{ max-height: \
             min(600px, calc(100% - 72px)) }}`"
        );
    }

    /// PIN (user ruling 2026-08-18) — **the height cap is the tallest everyday
    /// page, measured, and 600 is only the ceiling over it.**
    ///
    /// The three exclusions are the whole of the claim, and each is stated
    /// separately because each would fail differently. Open an `Advanced` group
    /// and the cap must not move — otherwise the dialog is permanently as tall
    /// as its longest possible page. Hand it a shortcut table or a profile list
    /// and the cap must not move — otherwise the dialog's height is a fact about
    /// the user's own files. And the answer must not depend on which tab layout
    /// this window is in, because the row that differs (`Sidebar`) is switched
    /// from a row on the very page it joins: a cap that followed the window
    /// would resize the dialog under the pointer.
    ///
    /// Red gate: drop `advanced: AdvancedOpen::default()` from [`everyday_cap`]
    /// and the second assertion goes red at 947; drop `shortcuts: &[]` and the
    /// third does; read `content.rows` instead of the maximal list and the
    /// fourth does, 54 apart.
    #[test]
    fn the_height_cap_is_the_tallest_everyday_page_and_not_a_number() {
        let metrics = StackMetrics::new(1.0);
        assert_eq!(
            dialog_around(everyday_cap(
                metrics,
                &values(),
                metrics.row_span(dialog_width()),
                &mut flat(0.0)
            )),
            everyday_cap_height(),
            "the sweep and the hand derivation are one number: the tallest page \
             under the vertical rail, its Advanced folded"
        );
        // **And since §7.1.6b′ it is over the ceiling, so the ceiling answers.**
        // This pin read `everyday_cap_height() < 600` while the derivation was
        // the smaller of the two; focus mode's row on `Appearance` took it past
        // 600, which is the case `DIALOG_MAX_HEIGHT_LOGICAL_PX`'s own doc rules
        // on — the page scrolls, the dialog stays a dialog. Both halves are
        // stated, because a build that let the dialog follow the derivation past
        // 600 would fail the second, and a build that stopped deriving at all
        // would fail the first.
        assert!(
            everyday_cap_height() > DIALOG_MAX_HEIGHT_LOGICAL_PX,
            "the tallest everyday page has outgrown the ceiling: {}",
            everyday_cap_height()
        );
        assert_eq!(
            capped_dialog_height(),
            DIALOG_MAX_HEIGHT_LOGICAL_PX,
            "so the dialog opens at the ceiling and that page scrolls, rather than the window being swallowed"
        );

        let rows = flat_rows();
        let lines = shortcut_lines();
        let profiles = profile_lines();

        // The two lists at every length a machine can hand over, the group both
        // ways, and both rails. **The shortcut table is in every one of them**
        // because it is in every dialog the app opens: forty lines is longer
        // than any page, so the cap is what answers, and what this loop is
        // pinning is that the answer never moves.
        for tab_layout in [TabLayoutMode::Horizontal, TabLayoutMode::Vertical] {
            let rows = visible_rows(tab_layout);
            for profiles in [&[][..], &profiles[..]] {
                for advanced in [AdvancedOpen::default(), every_group_open()] {
                    let placed = layout_for_menu(
                        SURFACE.0,
                        SURFACE.1,
                        1.0,
                        None,
                        None,
                        SettingsContent {
                            rows: &rows,
                            shortcuts: &lines,
                            profiles,
                            scheme_files: &[],
                            advanced,
                            advanced_reveal: None,
                            editor: None,
                            values: Box::leak(Box::new(SettingsValues::sample())),
                        },
                        SettingsCategory::Appearance,
                        UNSCROLLED,
                        MENU_UNSCROLLED,
                        &mut flat(0.0),
                    )
                    .expect("this window hosts the dialog");
                    assert_eq!(
                        height(placed.frame),
                        capped_dialog_height().round(),
                        "{tab_layout:?}: neither list nor an opened group nor \
                         the rail's own row may move the frame — {} profiles, \
                         group open {}",
                        profiles.len(),
                        advanced.is_open(SettingsCategory::Appearance)
                    );
                }
            }
        }

        // And the cap is a ceiling and not a floor: a dialog whose pages are all
        // shorter than it stays the height of its tallest page. This is the
        // fixture without the shortcut table, which no real window is, and it is
        // here so that "capped" is never mistaken for "padded out to".
        let short = layout_for_menu(
            SURFACE.0,
            SURFACE.1,
            1.0,
            None,
            None,
            SettingsContent {
                rows: &rows,
                shortcuts: &[],
                profiles: &[],
                scheme_files: &[],
                advanced: AdvancedOpen::default(),
                advanced_reveal: None,
                editor: None,
                values: Box::leak(Box::new(SettingsValues::sample())),
            },
            SettingsCategory::Appearance,
            UNSCROLLED,
            MENU_UNSCROLLED,
            &mut flat(0.0),
        )
        .expect("this window hosts the dialog");
        assert!(
            height(short.frame) < everyday_cap_height(),
            "with no table to be tall for, the tallest page is what answers: {}",
            height(short.frame)
        );
    }

    /// PIN (user ruling 2026-08-18) — **the dialog is optically centred: two
    /// parts of the window's slack above it and three below, never nearer the
    /// caption than 54.**
    ///
    /// The old rule was a flat 54 drop, which was right while the height was the
    /// window's own. Once the height stopped at a cap, a tall window put every
    /// spare pixel underneath and the dialog sat with its shoulders against the
    /// caption. 0.4 rather than 0.5 is the convention every system's dialogs
    /// obey and the ruling names: a box at the true middle of a rectangle reads
    /// as low.
    ///
    /// The floor is the second half. It binds exactly where the height was
    /// already clamped to the window, and there it hands the bottom margin back
    /// the 18 the clamp reserved — so the two margins are still the mock-up's
    /// two margins on the window that has nothing to spare.
    ///
    /// Red gate: drop the `.max(px(DIALOG_TOP_LOGICAL_PX))` and the short
    /// window's assertion goes red at 28; take the share to 0.5 and the tall
    /// window's does.
    #[test]
    fn the_dialog_is_optically_centred_and_never_rides_above_its_floor() {
        let rows = flat_rows();
        let lines = shortcut_lines();
        for surface_height in [1100.0_f32, 900.0, 700.0, 640.0, 400.0] {
            let placed = layout_for_menu(
                SURFACE.0,
                surface_height,
                1.0,
                None,
                None,
                content(&rows, &lines),
                SettingsCategory::Appearance,
                UNSCROLLED,
                MENU_UNSCROLLED,
                &mut flat(0.0),
            )
            .expect("every one of these windows hosts the dialog");
            let tall = height(placed.frame);
            let slack = surface_height - tall;
            assert!(
                placed.frame[1] >= DIALOG_TOP_LOGICAL_PX,
                "{surface_height}: the floor holds — {:?}",
                placed.frame
            );
            assert_eq!(
                placed.frame[1],
                (slack * DIALOG_OPTICAL_TOP_SHARE)
                    .max(DIALOG_TOP_LOGICAL_PX)
                    .round(),
                "{surface_height}: two parts above, three below"
            );
            assert!(
                surface_height - placed.frame[3] >= DIALOG_BOTTOM_LOGICAL_PX - 0.5,
                "{surface_height}: and the bottom margin the mock-up reserves \
                 survives the move — {:?} in {surface_height}",
                placed.frame
            );
        }

        // The two ends of the rule, named rather than swept: a window with room
        // to spare gives the share, and a window with none gives the floor.
        let roomy = layout_for_menu(
            SURFACE.0,
            1100.0,
            1.0,
            None,
            None,
            content(&rows, &lines),
            SettingsCategory::Appearance,
            UNSCROLLED,
            MENU_UNSCROLLED,
            &mut flat(0.0),
        )
        .expect("a 1100px window hosts the dialog");
        assert!(
            roomy.frame[1] > DIALOG_TOP_LOGICAL_PX,
            "1100 tall: the dialog comes down off the caption — {:?}",
            roomy.frame
        );
        let tight = layout_for_menu(
            SURFACE.0,
            400.0,
            1.0,
            None,
            None,
            content(&rows, &lines),
            SettingsCategory::Appearance,
            UNSCROLLED,
            MENU_UNSCROLLED,
            &mut flat(0.0),
        )
        .expect("a 400px window hosts the dialog");
        assert_eq!(
            tight.frame[1], DIALOG_TOP_LOGICAL_PX,
            "400 tall: the floor is what answers"
        );
        assert_eq!(
            tight.frame[3],
            400.0 - DIALOG_BOTTOM_LOGICAL_PX,
            "and the window's other margin is exactly what is left"
        );
    }

    /// PIN (user ruling 2026-08-19) — **`ADVANCED` stands where `APPEARANCE`
    /// does, and its chevron ends where every picker on the page ends.**
    ///
    /// Three treatments were drawn for the choosing — a gutter the page grew, a
    /// group-label heading with a small triangle, a trailing chevron with no
    /// leading mark — and the answer was a hybrid: the second one's word, the
    /// third one's mark, and no leading mark at all. That makes the header's two
    /// ends two different claims, and this pins both.
    ///
    /// The word is a HEADING, so it starts on the heading column: `text_left`,
    /// the same x the page's own `APPEARANCE` starts at, two pixels left of the
    /// rows because `.group-label` carries no `.row` padding. The chevron is a
    /// CONTROL, so it ends on the control column: `row_right`, byte-aligned with
    /// where every picker on the page ends. Nothing at all hangs to the left of
    /// the word — that is the whole of what the 2026-08-19 report asked for, and
    /// it is asserted rather than implied.
    ///
    /// Red gate: put the word back on the rows' own title column and the first
    /// assertion goes red two out; give the chevron back the leading gutter and
    /// the third goes red the width of the page.
    #[test]
    fn the_advanced_word_stands_on_the_heading_column_and_its_chevron_on_the_control_one() {
        let placed = shaped(SettingsCategory::Appearance, AdvancedOpen::default(), None);
        let group = placed.advanced().expect("Appearance has an Advanced group");
        let heading = placed
            .groups
            .first()
            .expect("a page heads itself with its own word")
            .label[0];
        assert_eq!(
            group.label[0], heading,
            "the word starts where the page's own heading starts"
        );
        // **The band holds the word with the same air a picker holds its value**
        // (user report 2026-08-19, screenshot). The band is what a press lands
        // in and what the focus ring is struck around, and it used to begin on
        // the word's own left edge — so the ring came down one pixel off the `A`
        // of `ADVANCED` while every combo on the same page held its value a
        // dozen pixels inside its box.
        //
        // Red gate: put `text_left` back as `band[0]` and this goes red by the
        // whole padding; move the *word* instead of the band and the assertion
        // above it goes red by the same amount.
        assert_eq!(
            group.label[0] - group.band[0],
            COMBO_PADDING_LEFT_LOGICAL_PX,
            "the word stands off its own band by a picker's own left padding"
        );
        assert_eq!(
            group.band[2] - group.mark[2],
            COMBO_PADDING_RIGHT_LOGICAL_PX,
            "and the chevron ends a picker's own right padding short of it"
        );
        assert!(
            group.band[0] < heading,
            "which puts the band outside the heading column rather than on it:              band {:?}, heading {heading}",
            group.band
        );
        let title = placed
            .rows
            .iter()
            .map(|row| row.title[0])
            .fold(f32::INFINITY, f32::min);
        assert!(
            heading < title,
            "the heading column is the rows' own less `.row`'s padding:              heading {heading} against title {title}"
        );
        let control = placed
            .rows
            .iter()
            .map(|row| row.combo[2])
            .fold(f32::NEG_INFINITY, f32::max);
        assert_eq!(
            group.mark[2], control,
            "the chevron ends where every picker on the page ends"
        );
        assert_eq!(
            width(group.mark),
            DISCLOSURE_CHEVRON_WIDTH_LOGICAL_PX,
            "the chevron keeps its 10"
        );
        assert_eq!(
            height(group.mark),
            DISCLOSURE_CHEVRON_HEIGHT_LOGICAL_PX,
            "and its 6"
        );
        assert!(
            group.label[2] <= group.mark[0],
            "nothing is drawn between the word and the mark, and nothing at all              stands left of the word: label {:?}, mark {:?}",
            group.label,
            group.mark
        );
        assert_eq!(
            height(group.band),
            2.0 * ROW_PADDING_Y_LOGICAL_PX + GROUP_LABEL_LINE_LOGICAL_PX,
            "the band is the group label's line box between the row's own              paddings, which is what changed when the type did"
        );
        assert!(
            MOCKUP.contains(
                ".adv-head { padding-left: 12px; padding-right: 10px; \
                 margin-left: -10px; margin-right: -8px; }"
            ),
            "`design/ui-mockup.html` puts the word on the heading column too — \
             the band wears the picker's own paddings outwards and the \
             asymmetric margins cancel `.row`'s 2px, so the word never moves \
             while the focus ring stops landing on the `A` (user report \
             2026-08-19)"
        );
        assert!(
            !MOCKUP.contains("data-adv"),
            "and the three-variant scaffolding is gone from it: one form is              chosen, so there is one form drawn"
        );
    }

    /// PIN (user report on a real window, 2026-08-19, "很多下拉栏都这样") —
    /// **a floating panel is OPAQUE UNDER ITS OWN HAIRLINE.**
    ///
    /// The hairline is translucent by declaration — `menu_border` at 24/255 —
    /// and it used to be the first thing laid down, with the face inset one
    /// border inside it. So the outline of an opaque panel was the one place the
    /// panel was see-through, and in this dialog that is not academic: every
    /// picker on a page shares one control column, an open menu stands squarely
    /// over the boxes of the rows beneath it, and their hairlines landed exactly
    /// under its hairline. Measured on the real window: `#5C5C5C` along the
    /// stretches of the menu's edge that covered dialog surface, `#797979` along
    /// the stretches that covered another combo's edge — one outline, two
    /// weights, and the doubling moving as the reader scrolled.
    ///
    /// Stated as a property of the quad list rather than as a count of quads, so
    /// that a future third plane is free to exist: at the panel's own edge, an
    /// opaque quad of the panel's face is laid down BEFORE the translucent one.
    /// That is `background-clip: border-box`, which is what the mock-up's
    /// `.combo-menu` gets from a browser for free.
    ///
    /// Red gate: put the hairline back in front of the face and the last
    /// assertion goes red; drop the hairline altogether and the one above it
    /// does.
    #[test]
    fn a_floating_panel_is_opaque_under_its_own_hairline() {
        let frame = [100.0, 100.0, 300.0, 200.0];
        let face = [0x2a, 0x2a, 0x2a];
        let hairline = [0xff, 0xff, 0xff];
        let mut quads: Vec<OverlayQuad> = Vec::new();
        push_float_window(
            &mut quads,
            frame,
            8.0,
            1.0,
            10.0,
            face,
            [0, 0, 0],
            0.18,
            0.09,
            hairline,
            24.0 / 255.0,
        );
        // Three points: the panel's own left edge, where the hairline runs and
        // where a covered row's own edge used to show through it; its middle,
        // which was never in doubt; and one pixel outside, which must stay the
        // shadow's business alone.
        let covering = |x: f32, y: f32| -> Vec<OverlayQuad> {
            quads
                .iter()
                .filter(|quad| {
                    x >= quad.rect[0] && x < quad.rect[2] && y >= quad.rect[1] && y < quad.rect[3]
                })
                .copied()
                .collect()
        };
        let middle_y = (frame[1] + frame[3]) / 2.0;
        for x in [frame[0] + 0.5, frame[2] - 0.5] {
            let over = covering(x, middle_y);
            let hair = over
                .iter()
                .position(|quad| quad.color == hairline)
                .unwrap_or_else(|| panic!("the hairline runs along x = {x}"));
            assert!(
                over[..hair]
                    .iter()
                    .any(|quad| quad.color == face && quad.alpha == 1.0),
                "x = {x}: the panel's own ground goes down before its edge does,                  so the edge is composited over the panel and never over what                  the panel covers: {over:?}"
            );
        }
        assert!(
            covering((frame[0] + frame[2]) / 2.0, middle_y)
                .iter()
                .any(|quad| quad.color == face && quad.alpha == 1.0),
            "and the middle of the panel is its face at full strength"
        );
    }

    /// Every category the dialog can show holds at least one row, and a
    /// category's rows are contiguous — the order in [`visible_rows`] is what
    /// the page heading is derived from, so a row filed out of order would head
    /// its own page twice.
    #[test]
    fn each_categorys_rows_stand_together_in_the_visible_order() {
        for tab_layout in [TabLayoutMode::Horizontal, TabLayoutMode::Vertical] {
            let rows = visible_rows(tab_layout);
            let mut seen: Vec<SettingsCategory> = Vec::new();
            for row in rows {
                let group = row.category();
                if seen.last() != Some(&group) {
                    assert!(
                        !seen.contains(&group),
                        "{tab_layout:?}: {group:?} is interrupted by another category"
                    );
                    seen.push(group);
                }
            }
            assert_eq!(
                seen,
                vec![
                    SettingsCategory::Appearance,
                    SettingsCategory::RenderedBlocks,
                    SettingsCategory::General,
                    SettingsCategory::Terminal,
                    SettingsCategory::Agents,
                ],
                "{tab_layout:?}: every category with rows is shown once, its rows \
                 together"
            );
        }
    }

    /// PIN (S4, 2026-08-17) — **every row is on exactly one page, and every page
    /// the rail offers has something on it.**
    ///
    /// The first half is what makes the rail a partition rather than a filter:
    /// a row filed nowhere is a control nobody can reach, and a row filed twice
    /// is a switch that disagrees with itself two words apart.
    ///
    /// The second is the placeholder ruling, stated as a property: the rail is
    /// the categories that **have** rows, in declaration order, and nothing
    /// else. `Terminal` is the proof it works from both sides — it sat in
    /// `ALL` with a heading and a page and stayed out of the rail for two
    /// slices, and it joined the rail the day §7.1.6c-3b's PSReadLine row gave
    /// it content, with no list of rail items edited anywhere. A door onto an
    /// empty room is a worse promise than no door.
    ///
    /// MUTATIONS:
    /// (1) take **both** Terminal rows out of `visible_rows` — `Terminal` leaves
    ///     the rail on its own, which is the derivation working. It is two rows
    ///     rather than one since P2-9 slice 2 put `Scrollback` beside the
    ///     PSReadLine row, and that is the derivation working from the other
    ///     side: the page stays because something is still on it;
    /// (2) list the categories in the rail from `ALL` without the filter — a
    ///     category with nothing on it appears and this goes red.
    #[test]
    fn every_row_is_on_exactly_one_page_and_every_page_in_the_rail_has_something_on_it() {
        for tab_layout in [TabLayoutMode::Horizontal, TabLayoutMode::Vertical] {
            let rows = visible_rows(tab_layout);
            let lines = shortcut_lines();
            let content = content(&rows, &lines);
            for row in &rows {
                let homes: Vec<SettingsCategory> = SettingsCategory::ALL
                    .into_iter()
                    .filter(|category| content.page_rows(*category).contains(row))
                    .collect();
                assert_eq!(homes.len(), 1, "{row:?} is filed on {homes:?}");
                assert_eq!(homes[0], row.category());
            }
            let rail = content.nav_items();
            for category in &rail {
                assert!(
                    content.has_content(*category),
                    "{category:?} is in the rail with nothing on it"
                );
            }
            assert_eq!(
                rail,
                vec![
                    SettingsCategory::General,
                    SettingsCategory::Appearance,
                    SettingsCategory::Terminal,
                    SettingsCategory::Agents,
                    SettingsCategory::RenderedBlocks,
                    SettingsCategory::Shortcuts,
                ],
                "{tab_layout:?}: the rail is the categories with content, in \
                 declaration order"
            );
            // The other direction of the same rule, stated where it can still
            // be stated now that every category has content: strike the rows
            // of any one page and its word must leave the rail on its own.
            for absent in SettingsCategory::ALL {
                let kept: Vec<SettingsRow> = rows
                    .iter()
                    .copied()
                    .filter(|row| row.category() != absent)
                    .collect();
                let thinner = SettingsContent {
                    rows: &kept,
                    profiles: &[],
                    scheme_files: &[],
                    shortcuts: if absent == SettingsCategory::Shortcuts {
                        &[]
                    } else {
                        &lines
                    },
                    advanced: AdvancedOpen::default(),
                    advanced_reveal: None,
                    editor: None,
                    values: Box::leak(Box::new(SettingsValues::sample())),
                };
                assert!(
                    !thinner.nav_items().contains(&absent),
                    "{absent:?} keeps its word in the rail with nothing on its                      page — a door onto an empty room"
                );
            }
            assert_eq!(
                content.first_category(),
                SettingsCategory::General,
                "the dialog opens on the first word of the rail"
            );
        }
    }

    /// PIN (§7.1.6c-5) — **the page that shows the answer is a page that asks
    /// the question.**
    ///
    /// `Terminal` is the one page in this dialog drawn out of an out-of-band
    /// reading, and until this slice the reading was started by the first
    /// `Windows PowerShell` pane and by nothing else. Every user who opens WSL
    /// or `pwsh` and never a 5.1 pane therefore read "Checking this machine's
    /// PSReadLine" for as long as they cared to look — a row waiting on an
    /// answer nobody had asked for.
    ///
    /// The trigger is derived from the row rather than named as a category,
    /// which is what the second half pins: no other page asks, and the day the
    /// row moves the asking moves with it.
    ///
    /// Red gate: return `false` unconditionally and the first assertion goes
    /// red; return `true` for every page and the loop does.
    #[test]
    fn showing_the_page_the_probe_answers_on_is_what_starts_the_probe() {
        let rows = visible_rows(TabLayoutMode::Horizontal);
        let lines = shortcut_lines();
        let content = content(&rows, &lines);
        assert!(
            content.probes_psreadline(SettingsCategory::Terminal),
            "the page holding the PSReadLine row is the page that starts the \
             probe"
        );
        for category in SettingsCategory::ALL {
            if category == SettingsCategory::Terminal {
                continue;
            }
            assert!(
                !content.probes_psreadline(category),
                "{category:?} starts a process to answer a question it does not \
                 draw"
            );
        }
        // The derivation, not the name: a build whose row list has lost the row
        // has no page that asks, whatever the categories are called.
        let without: Vec<SettingsRow> = rows
            .iter()
            .copied()
            .filter(|row| *row != SettingsRow::PsReadLine)
            .collect();
        let thinner = SettingsContent {
            rows: &without,
            shortcuts: &lines,
            profiles: &[],
            scheme_files: &[],
            advanced: AdvancedOpen::default(),
            advanced_reveal: None,
            editor: None,
            values: Box::leak(Box::new(SettingsValues::sample())),
        };
        for category in SettingsCategory::ALL {
            assert!(
                !thinner.probes_psreadline(category),
                "{category:?} asks for an answer no row on it would print"
            );
        }
    }

    /// PIN — the Startup row is the picker built from the `˅` menu's own list,
    /// and the only one in this dialog whose items wear a mark.
    ///
    /// Mock-up 7645: "the default-profile picker is built from the same list the
    /// ⌄ menu uses" — the *same* table, so a fifth profile appears in both
    /// surfaces or in neither, and 7647 is the one `.ticon` in any combo item.
    #[test]
    fn the_startup_row_offers_the_pickers_own_profiles_each_under_its_own_mark() {
        assert_eq!(
            SettingsRow::DefaultProfile.title(),
            "Default profile",
            "mock-up 2467"
        );
        assert_eq!(
            SettingsRow::DefaultProfile.description(&values()),
            "Which profile a new tab opens, and which one Folio starts with.",
            "the copy ruling of 2026-08-26, which supersedes mock-up 2468's own \
             wording — see docs/plans/ui-style/copy-guide.md"
        );
        assert_eq!(
            SettingsRow::DefaultProfile
                .option_labels()
                .collect::<Vec<_>>(),
            (0..profiles::count())
                .map(profiles::title)
                .collect::<Vec<_>>(),
        );
        for index in 0..profiles::count() {
            assert_eq!(
                SettingsRow::DefaultProfile.option_mark(index),
                Some(profiles::mark(index)),
                "{} wears its own mark, not a generic shell glyph",
                profiles::id(index)
            );
            assert_eq!(
                default_profile_requested(SettingsTarget::Choice(
                    SettingsRow::DefaultProfile,
                    index
                )),
                Some(profiles::id(index)),
                "the press asks for a profile by id — an index would not survive \
                 the table being reordered"
            );
        }
        // **One of two**, and the second one arrived for this one's reason
        // (user ruling, 2026-08-16): `Split direction` names two axes, and the
        // difference between "beside" and "below" is a shape this build already
        // draws. Every other picker's items are words, because every other
        // picker's items *are* words — `Light`, `Bar`, `On` name no object.
        for row in visible_rows(TabLayoutMode::Vertical) {
            if matches!(
                row,
                SettingsRow::DefaultProfile | SettingsRow::SplitDirection
            ) {
                continue;
            }
            for index in 0..row.option_count() {
                assert_eq!(row.option_mark(index), None, "{row:?} draws no marks");
            }
        }
        for (index, direction) in SPLIT_DIRECTION_OPTIONS.iter().enumerate() {
            assert_eq!(
                SettingsRow::SplitDirection.option_mark(index),
                Some(split_direction_mark(*direction)),
                "{direction:?} wears the glyph the rest of the product draws it with"
            );
            assert_eq!(
                split_direction_requested(SettingsTarget::Choice(
                    SettingsRow::SplitDirection,
                    index
                )),
                Some(*direction),
            );
        }
        assert_eq!(
            SettingsRow::SplitDirection
                .option_labels()
                .collect::<Vec<_>>(),
            vec!["Auto (longer edge)", "Right", "Down"],
        );
    }

    /// PIN (DESIGN §2.6) — **the `Minimum contrast` row goes round**: every rung the picker
    /// draws is a rung a press asks for, and a rung the file holds is the rung the tick lands
    /// on.
    ///
    /// The two halves are the two directions a picker has to work in, and they are separate
    /// functions that could disagree: `minimum_contrast_requested` turns an index into a value
    /// on the way in, `selected_index` turns a value back into an index on the way out. A row
    /// whose option list was reordered in one place and not the other would show the tick on
    /// `3:1` and write `2:1`, and only a test that walks both directions on the same index
    /// catches it.
    ///
    /// The label assertion is the third thing that can drift: `Off` comes out of the i18n table
    /// and the three ratios out of a parallel array, so an index that fell out of step between
    /// [`MINIMUM_CONTRAST_OPTIONS`] and [`MINIMUM_CONTRAST_LABELS`] would draw `2:1` on the
    /// item that means `3:1`.
    ///
    /// Red gate: swap two entries of `MINIMUM_CONTRAST_OPTIONS` and the round trip still passes
    /// while the labels go red; swap two of `MINIMUM_CONTRAST_LABELS` and only the labels do.
    #[test]
    fn the_minimum_contrast_row_goes_round() {
        assert_eq!(
            SettingsRow::MinimumContrast.option_count(),
            MINIMUM_CONTRAST_OPTIONS.len()
        );
        assert_eq!(
            SettingsRow::MinimumContrast
                .option_labels()
                .collect::<Vec<_>>(),
            vec!["Off", "2:1", "3:1", "4.5:1"],
        );
        for (index, floor) in MINIMUM_CONTRAST_OPTIONS.iter().enumerate() {
            assert_eq!(
                minimum_contrast_requested(SettingsTarget::Choice(
                    SettingsRow::MinimumContrast,
                    index
                )),
                Some(*floor),
                "item {index} does not ask for the value drawn on it"
            );
            let mut values = values();
            values.minimum_contrast = *floor;
            assert_eq!(
                SettingsRow::MinimumContrast.selected_index(&values),
                Some(index),
                "a file holding {floor:?} does not tick item {index}"
            );
        }
        // Off is the row's default and the first item, which is what makes a reader who has
        // never touched it see the tick where the ladder starts.
        assert_eq!(MINIMUM_CONTRAST_OPTIONS[0], MinimumContrastV1::Off);
        assert_eq!(
            SettingsRow::MinimumContrast.selected_index(&values()),
            Some(0)
        );
        // A press on a *different* row must never be read as a contrast request — the router
        // calls every `*_requested` in turn on the same target.
        assert_eq!(
            minimum_contrast_requested(SettingsTarget::Choice(SettingsRow::SplitDirection, 1)),
            None
        );
    }

    /// PIN — the combo reads the app's state, and the app's state is the
    /// *resolved* default.
    ///
    /// **The mock-up's own bug, deliberately not copied** (2471): its combo
    /// button is born holding the literal string `PowerShell` and only ever
    /// updates when the user picks something, so a default that was not index 0
    /// showed stale words until touched. `selected_index` reading `values` is the
    /// whole of the fix, and this pins that the button's caption is derived from
    /// it rather than from a constant.
    ///
    /// Said through [`ellipsized`] rather than against the bare title, because
    /// two of these profiles are named longer than 118px of button can hold and
    /// the row would otherwise be asserting that the fit never happens. What the
    /// pin still forbids is the thing it was written for: a caption that does not
    /// come from `chosen` fails here for every other profile in the table.
    #[test]
    fn the_default_profile_combo_shows_the_profile_that_would_actually_start() {
        for chosen in 0..profiles::count() {
            let values = SettingsValues {
                default_profile: chosen,
                ..values()
            };
            assert_eq!(
                SettingsRow::DefaultProfile.selected_index(&values),
                Some(chosen)
            );
            let placed = open_showing(SettingsRow::DefaultProfile);
            let combo = placed
                .row(SettingsRow::DefaultProfile)
                .expect("the Startup row is in the dialog")
                .combo;
            let caption = labels_of(&placed, None, &values)
                .into_iter()
                .find(|label| label.rect[1] >= combo[1] && label.rect[3] <= combo[3])
                .expect("the closed combo shows its current value");
            let box_of = combo_value_box(combo);
            assert_eq!(
                caption.text,
                ellipsized(
                    profiles::title(chosen),
                    width(box_of),
                    COMBO_FONT_LOGICAL_PX,
                    &mut measure
                ),
                "the button says what the `+` would start"
            );
        }
    }

    /// PIN — a profile this machine cannot start is greyed *and* unclickable, and
    /// the two are one answer.
    ///
    /// The picker menu's ruling (`profiles::hit`) applied to the dialog, because
    /// it is the same fact about the same machine: a rule spelled only at the
    /// click lights the row under the pointer and then does nothing when pressed;
    /// a rule spelled only at the draw leaves the item dark and still selectable.
    /// So the press, the hover and the ink are asserted together.
    #[test]
    fn a_shell_this_machine_lacks_is_greyed_in_the_startup_picker_and_cannot_be_chosen() {
        let missing = profiles::index_of_id("gitbash");
        let mut available = vec![true; profiles::count()];
        available[missing] = false;
        let lacking = SettingsValues {
            profile_available: available,
            ..values()
        };
        let placed = open_rows(
            1.0,
            Some(SettingsRow::DefaultProfile),
            TabLayoutMode::Horizontal,
        );
        let item = placed.items[missing];
        let centre = (
            f64::from((item[0] + item[2]) / 2.0),
            f64::from((item[1] + item[3]) / 2.0),
        );

        // **The press names the item and still chooses nothing** (§7.47). It
        // used to arrive as the menu's own body, which is what made a refusal
        // impossible to explain; what has to stay true is the half that is
        // about this row — no profile was asked for, so the runtime stores
        // nothing and the menu stays up.
        assert_eq!(
            hit(&placed, &lacking, centre.0, centre.1),
            SettingsTarget::ChoiceRefused(SettingsRow::DefaultProfile, missing),
            "the press lands on the item, greyed"
        );
        assert_eq!(
            default_profile_requested(hit(&placed, &lacking, centre.0, centre.1)),
            None,
            "and nothing was chosen: a row with no reason to give says nothing \
             and changes nothing, exactly as it did when the press was thrown \
             away"
        );
        assert_eq!(
            hit(&placed, &values(), centre.0, centre.1),
            SettingsTarget::Choice(SettingsRow::DefaultProfile, missing),
            "and on a machine that has Git Bash the very same point chooses it"
        );

        let palette = bt_render::chrome_palette();
        let mark = sprites_of(&placed, None, &lacking)
            .into_iter()
            .find(|sprite| sprite.mark == profiles::mark(missing))
            .expect("the greyed item still draws its mark");
        assert_eq!(mark.opacity, UNAVAILABLE_MARK_OPACITY);
        assert!(mark.grayscale, "and it loses its colours saying so");
        let label = labels_of(&placed, None, &lacking)
            .into_iter()
            .find(|label| label.text == profiles::title(missing))
            .expect("the greyed item is still named");
        assert_eq!(
            label.color, palette.menu_item_hint_text,
            "the quietest ink this surface has, which is what it already uses \
             for text that reports rather than offers"
        );

        // A hover that somehow arrived on it lights nothing — the two halves
        // cannot come apart, which is the whole reason `option_enabled` is asked
        // by the draw as well as by the hit test.
        let hovered = SettingsTarget::Choice(SettingsRow::DefaultProfile, missing);
        assert_eq!(
            labels_of(&placed, Some(hovered), &lacking)
                .into_iter()
                .find(|label| label.text == profiles::title(missing))
                .map(|label| label.color),
            Some(palette.menu_item_hint_text),
        );
    }

    /// PIN — the marked picker makes room for its marks.
    ///
    /// `min-width: 100%` is a floor and the popup grows leftward to hold its
    /// widest label; an item that also carries a 14px `.ticon` and its 10px gap
    /// needs 24px more than that label, and a popup sized without them crops the
    /// last glyph of every profile name.
    #[test]
    fn the_marked_picker_reserves_its_icon_column_on_top_of_the_widest_label() {
        for scale in [1.0_f32, 1.5, 2.0] {
            let widest = 120.0 * scale;
            let marked = open_rows_measured(
                scale,
                Some(SettingsRow::DefaultProfile),
                TabLayoutMode::Horizontal,
                widest,
            );
            let plain = open_rows_measured(
                scale,
                Some(SettingsRow::Theme),
                TabLayoutMode::Horizontal,
                widest,
            );
            let width = |placed: &SettingsLayout| {
                let menu = placed.menu.expect("the picker is open");
                menu[2] - menu[0]
            };
            assert_eq!(
                width(&marked) - width(&plain),
                ((OPTION_ICON_COLUMN_LOGICAL_PX + ITEM_GAP_LOGICAL_PX) * scale).ceil(),
                "scale {scale}: exactly the column and its gap, and not a pixel \
                 of slack invented here"
            );
        }
    }

    /// The dialog's close affordance is the house's own `#i-cross`, and it is
    /// the only mark the **header** draws.
    ///
    /// It was the mock-up's `#i-close` at the caption's ten until 裁2
    /// (2026-08-26): the dialog is this house's surface and not Windows's, so
    /// its cross is the house's, and a house drawing takes the compact head's
    /// box — thirteen, with ten units of ink inside it, which is a *smaller*
    /// picture than the ten-unit cross that filled its own box.
    ///
    /// "The only mark the overlay draws" until §7.1.6c-5, when the Advanced
    /// disclosure gave the scrolling stack one of its own — the house's
    /// chevron since the 2026-08-26 ruling, which keeps the filled triangle in
    /// the files tree and on a submenu row. So the claim is stated where it is
    /// still true and where it matters: the header holds one mark, and it is
    /// this one.
    #[test]
    fn the_close_affordance_wears_the_mock_ups_own_close_symbol() {
        let placed = open(1.0, true);
        let sprites = sprites_of(&placed, None, &values());
        let closes: Vec<_> = sprites
            .iter()
            .filter(|sprite| sprite.mark == ChromeMark::TabClose)
            .collect();
        assert_eq!(closes.len(), 1, "one close, and only one");
        assert!(
            sprites.iter().all(|sprite| matches!(
                sprite.mark,
                ChromeMark::TabClose | ChromeMark::Chevron { .. }
            )),
            "the overlay's marks are the close and the disclosure's chevron,              and nothing has quietly joined them: {:?}",
            sprites.iter().map(|sprite| sprite.mark).collect::<Vec<_>>()
        );
        let glyph = closes[0].rect;
        assert_eq!(
            width(glyph),
            crate::seats::compact_head_glyph_logical_px(ChromeMark::TabClose),
            "the close icon takes the compact head's box",
        );
        assert_eq!(width(glyph), 13.0);
        assert_eq!(height(glyph), 13.0);
        assert!(
            (((glyph[0] + glyph[2]) / 2.0) - ((placed.close[0] + placed.close[2]) / 2.0)).abs()
                <= 0.5,
            "the icon is centred in its 30px button"
        );
    }

    /// PIN (user screenshot 2026-08-10): `min-width: 100%` is a **floor**.
    ///
    /// The popup used to take the button's width as its size outright, so an
    /// option longer than its button was cropped mid-glyph and the item's own
    /// hover pill was cropped with it. The measured label now sets the width
    /// when it is the larger of the two, and the arithmetic is stated here in
    /// the numbers the stylesheet uses: the box must hold the text *plus* the
    /// chrome around it, which is the menu's two borders and padding, the item's
    /// padding on both sides, the fixed tick column and the gap after it.
    #[test]
    fn a_picker_wider_than_its_button_grows_to_hold_its_longest_option() {
        // Wider than the 118px button can hold, so the floor loses and the text wins.
        const MEASURED: f32 = 200.0;
        let placed = open_rows_measured(
            1.0,
            Some(SettingsRow::Sidebar),
            TabLayoutMode::Vertical,
            MEASURED,
        );
        let menu = placed.menu.expect("the picker is open");
        let combo = combo_of(&placed, SettingsRow::Sidebar);
        let chrome = 2.0 * 1.0
            + 2.0 * MENU_PADDING_LOGICAL_PX
            + 2.0 * ITEM_PADDING_X_LOGICAL_PX
            + TICK_WIDTH_LOGICAL_PX
            + ITEM_GAP_LOGICAL_PX;

        assert!(
            width(menu) > width(combo),
            "a label too wide for the button must widen the popup, not be cut by it"
        );
        assert_eq!(width(menu), chrome + MEASURED);
        assert_eq!(
            menu[2], combo[2],
            "`right: 0` still holds - the extra width is taken on the left"
        );

        // The item, its pill and its text all inherit the new width, which is
        // the half the screenshot actually showed: a cropped pill under cropped
        // words.
        let item = placed.items[0];
        assert_eq!(
            item[2] - item[0],
            width(menu) - 2.0 * 1.0 - 2.0 * MENU_PADDING_LOGICAL_PX
        );
        let labels = labels_of(&placed, None, &values());
        // The closed button draws this word too, so the popup's own copy is the
        // one inside the popup — picking the first match finds the button's.
        let drawn = labels
            .iter()
            .find(|label| label.text == "Expanded" && overlaps(label.rect, menu))
            .expect("the option is drawn inside the picker");
        assert!(
            width(drawn.rect) >= MEASURED,
            "the text's own box must not be narrower than the text it holds: {} < {MEASURED}",
            width(drawn.rect)
        );
        assert!(
            within(drawn.rect, menu),
            "and it must stay inside the popup that drew it"
        );
    }

    /// PIN: the widening is conditional, so every picker that shipped before it
    /// is untouched. Theme, Cursor and Tab layout each wear one short word, and
    /// a short word must leave the popup exactly as wide as its button.
    #[test]
    fn a_picker_whose_options_all_fit_keeps_the_button_width_it_always_had() {
        for (row, tab_layout) in [
            (SettingsRow::Theme, TabLayoutMode::Horizontal),
            (SettingsRow::Cursor, TabLayoutMode::Horizontal),
            (SettingsRow::Formulas, TabLayoutMode::Horizontal),
            (SettingsRow::TabLayout, TabLayoutMode::Horizontal),
            (SettingsRow::Sidebar, TabLayoutMode::Vertical),
        ] {
            // 40px of glyphs is roomier than any of these words needs and still
            // fits inside the button, so the floor must win.
            let placed = open_rows_measured(1.0, Some(row), tab_layout, 40.0);
            let menu = placed.menu.expect("the picker is open");
            let combo = combo_of(&placed, row);
            assert_eq!(
                width(menu),
                width(combo),
                "{row:?}: a picker whose options fit must not grow a pixel"
            );
        }
    }

    /// PIN: a popup too wide for the window is pulled back inside it, the same
    /// clamp `profiles`, `tooltip` and `peek_strip` each apply to their own
    /// floating boxes.
    #[test]
    fn a_picker_too_wide_for_the_window_is_clamped_into_it() {
        let rows = flat_rows();
        let placed = layout_for_menu(
            780.0,
            800.0,
            1.0,
            Some(SettingsRow::Theme),
            None,
            content(&rows, &[]),
            PAGE,
            UNSCROLLED,
            MENU_UNSCROLLED,
            &mut flat(4_000.0),
        )
        .expect("the dialog still fits this window");
        let menu = placed.menu.expect("the picker is open");
        assert!(
            menu[0] >= 0.0,
            "the popup must not start off the left edge of the window: {menu:?}"
        );
    }

